quests[10322] = { id = 10322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shutting Down Manaforge Duro", description = "We've received news from one of the two manaforges that remain operational.  The Sunfury army is losing control of Manaforge Duro.\n\nDroves of errant mana creatures have been attracted to it by its increased energy production - the manaforge is in chaos.\n\nAn explosion at Duro has the potential to cause a chain reaction that would endanger all of Outland.  Overseer Athanel is in possesion of the access crystal you need to safely disable the manaforge.", sourceObjective = "Anchorite Karja wants you to go Manaforge Duro and obtain the Duro Access Crystal from Overseer Athanel. Use it at the Manaforge Duro Console to shut it down.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you completed your task yet, {name}?", completion = "You are blessed by the naaru, {name}.  Your dedication to the cause will not go unnoticed or unrewarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[10323] = { id = 10323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shutting Down Manaforge Ara", description = "One manaforge is all that keeps Tempest Keep functional.  After we bring Manaforge Ara down, Kael will have to resort to depleting whatever energy he's got stored up.\n\nTravel to Manaforge Ara, in the northwest, and deliver the final blow that we need by shutting it down.\n\nThe last access crystal is in the possession of Overseer Azarad.  Be warned that we expect heavy opposition in the last of Kael's functional manaforges.  You're likely to need the assistance of reliable friends.", sourceObjective = "Travel to Manaforge Ara and obtain the Ara Access Crystal from Overseer Azarad. Use it at the Manaforge Ara console to shut it down.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you completed the task I asked of you, {name}?", completion = "The Burning Legion?  Allied with Kael'thas Sunstrider?\n\nThis is dire news.  It explains much about what we've seen here and in Shadowmoon.\n\nWe must send word back to Shattrath City immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[10324] = { id = 10324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Moongraze Hunt", description = "Well done, {name}! Well done!\n\nNow that you've cut your teeth with the moongraze stag, it's time you graduated to more formidable prey. Do not allow the casual disinterest of the moongraze bucks to fool you: when provoked, they are a fearsome foe.\n\nYou'll find the bucks north of here. Good hunting.", sourceObjective = "Bring 6 Moongraze Buck Hides to Acteon at Azure Watch.", progress = "The buck hides are rugged and strong, making for very tough flesh - almost inedible, but we can use them for other purposes.", completion = "Wonderful! You're turning into quite the hunter, {name}.\n\nHow would you like to look more like me? Well here is your chance! While you were out hunting, I fashioned these items out of some buck hides I had laying around. Take your pick!", sourceObjectiveStatus = "unverified-source-field" }
quests[10325] = { id = 10325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marks of Kil'jaeden", description = "As you probably know, {name}, the Aldor are keepers of the Light and servants of the naaru.\n\nDiametrically opposed to us are the agents of the Burning Legion - demons bent on the destruction of worlds and the corruption of the innocent.\n\nIf you wish to prove yourself to the Aldor, bring me the insignias of low-ranking Legion and their Shadow Council followers.  We know of a Shadow Council hideout in the Bone Wastes and there are many Legion outposts in Nagrand and the Blade's Edge Mountains.", sourceObjective = "Bring 10 Marks of Kil'jaeden to Adyen the Lightwarden in Shattrath City.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Do you bear any of our enemies' insignias, {name}?", completion = "Facing the demons of the Burning Legion and the mad cultists that worship them is no small feat, {name}.  You've shown great dedication and courage.  Keep it up and your renown among the Aldor will continue to grow.", sourceObjectiveStatus = "unverified-source-field" }
quests[10326] = { id = 10326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Marks of Kil'jaeden", progress = "Do you bear more of our enemies' insignias, {class}?  The Burning Legion continues to be a threat and we continue to pursue them anywhere that we find them.", completion = "You continue to prove your worth, {name}.  Fight the enemies of the Light wherever you may find them; your actions will be well-rewarded." }
quests[10327] = { id = 10327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Single Mark of Kil'jaeden", progress = "I'll take any leftover marks you might have.  Do not worry; your actions will be duly noted.", completion = "You continue to prove your worth, {name}.  Fight the enemies of the Light wherever you may find them; your actions will be well-rewarded." }
quests[10328] = { id = 10328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunfury Briefings", description = "Something about these manaforges has been bothering me, {name}.  Naaru technology is incredibly advanced; it should've taken Kael'thas years to even begin to understand it.\n\nInformation-gathering on the subject has been difficult as Kael's army is well disciplined and destroys all evidence of written communication.\n\nWe've been informed Manaforge Duro is under attack by mana creatures.  It is possible that those defending it have not yet destroyed their briefings.  Obtain them and bring them to me.", sourceObjective = "Go to Manaforge Duro and retrieve the Sunfury Military Briefing and the Sunfury Arcane Briefing from the Sunfury units stationed there. Return to Exarch Orellis when you've completed this task.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Did you have any luck with the briefings from Manaforge Duro?", completion = "Excellent job, {name}!  Let us see what can be learned from these briefings.", sourceObjectiveStatus = "unverified-source-field" }
quests[10329] = { id = 10329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shutting Down Manaforge B'naar", description = "I was having a friendly discussion with the Aldor while you were gone.  Manaforges sure look like modified naaru technology from Tempest Keep.  Apparently, most naaru constructs have certain safeguards that allow them to be permanently disabled in case of emergency.\n\nThe procedure is usually initiated at a control console via an access crystal.  Lo and behold, according to the roster you secured, such a crystal is in the possession of a fellow called Overseer Theredis.  Obtain it and see what you can do.", sourceObjective = "Return to Manaforge B'naar and obtain the B'naar Access Crystal from Overseer Theredis. Use it at the B'naar Control Console to shut it down, then report back to Spymaster Thalodien.\n\nPerforming quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Did the plan work?  I was half-expecting you to get blown up, to tell you the truth.", completion = "Of course it worked!  I'm a spymaster; my information is always accurate.\n\nAnyhow, I have a whole new exciting job lined up for you.  You want to hear about it?  Of course you do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10330] = { id = 10330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shutting Down Manaforge Coruu", description = "Thalodien told us of your success in disabling Manaforge B'naar.  He expects a repeat performance here and asked us to keep an eye out for anyone using a crystal to access the console inside.  Overseer Seylanna holds the access crystal, we're sure of it.\n\nGo back in there and finish the operation.  No need to be stealthy anymore; get the crystal, begin the shutdown, kill the technicians trying to stop you and get out.\n\nHurry, it won't be long before Kael's lapdogs sniff us out.", sourceObjective = "Obtain the Coruu Access Crystal from Overseer Seylanna. Use it at the Coruu Control Console to shut down the manaforge and return to Caledis Brightdawn.\n\nPerforming quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Have you completed your task yet, {name}?", completion = "We heard all the commotion and were just about to leave.  Glad to see you didn't take too bad of a beating.", sourceObjectiveStatus = "unverified-source-field" }
quests[10331] = { id = 10331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Indispensable Tools", description = "You haven't seen a heavy smithing hammer lying around by chance, have you? I brought it out here with me to finish the shoes for some of old man Amorlin's horses, but I can't find it.\n\nI've searched the barn no less than a half dozen times and I just can't seem to find it. Maybe one of the other apprentices retrieved it and took it back to the smithy? Would you be willing to go down there and take a look? The workshop is to the southeast of the tower in the Town Square.", sourceObjective = "Retrieve the Smithing Hammer from the Kirin'Var Apprentices and bring it back to Apprentice Andrethan in Kirin'Var Village.", progress = "Did you have any luck finding my hammer?", completion = "Thank goodness! Now I can get back to work. I know you think I'm crazy, working on the piece that will earn me journeyman status away from the forge proper, but I can't run the risk of one of the other apprentices copying my design.", sourceObjectiveStatus = "unverified-source-field" }
quests[10332] = { id = 10332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master Smith Rhonsus", description = "At last, my journeyman project is complete! I can't wait to formally present it to Master Rhonsus.\n\n<The apprentice looks at you as you describe your experiences retrieving the hammer.>\n\nThey attacked you? All of them? By the Light, they've gone mad!\n\nWhat are we to do, {name}? It grieves me to say so, but it may be necessary to kill Master Rhonsus. It would leave me as the only smith in Kirin'Var, but I believe my training is sufficient to serve the town's needs.", sourceObjective = "Apprentice Andrethan in Kirin'Var Village wants you to kill the ghost of Rhonsus, the town's master blacksmith.", progress = "<There appear to be tears in the apprentice's eyes as he speaks.>\n\nHave you... dealt with Master Rhonsus?", completion = "Master Rhonsus taught me everything I know about my trade. I will honor his memory by using my skills to serve the people of Kirin'Var.", sourceObjectiveStatus = "unverified-source-field" }
quests[10333] = { id = 10333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Mama Wheeler", description = "Say, {name}, I was wondering if you could do me another favor.\n\nMy partner out in the field could probably use a hand.  I was wondering if you could go check in on her.\n\nI'm sure that Mama Wheeler will appreciate the help.  Just don't mind her sharp tongue.\n\nShe's trying to look out for our interests to the east.  You'll find her just inside Eco-Dome Midrealm at the Midrealm Post.", sourceObjective = "Speak with Mama Wheeler at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.", completion = "What?!  He called me his 'partner'?  I'm his wife!\n\nAnd he said I had a sharp tongue!  Ooh, when I get back to Area 52, I'm going to box his big, green ears!\n\nBut I'm glad that you're here.  He was right about one thing; I can definitely use your help!", sourceObjectiveStatus = "unverified-source-field" }
quests[10334] = { id = 10334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Needs More Cowbell", description = "Where, oh where has my Bessy gone? After the attack, I searched the fields and the Chapel Yard for her, but she was nowhere to be seen!\n\nAll I have left of her is this old cowbell. She usually comes running when she hears it, but these feeble old bones probably couldn't shake it hard enough.\n\nI'll loan you Bessy's bell if you're willing to go out to the fields and ring it as hard as you can. Perhaps all Bessy's waiting for is a little more cowbell.", sourceObjective = "Find Bessy in the fields near Kirin'Var Village's Chapel Hill in Netherstorm.", progress = "<The cow looks at you distrustfully, but stands its ground.>", completion = "<Removing the bell from your pack, you ring it a couple of times and show it to Bessy, who seems to recognize it. The cow allows the bell's cord to be fastened around her neck and looks at you expectantly.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10335] = { id = 10335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surveying the Ruins", description = "I have to get over to the Ruins of Farahlon to start my excavations!  The problem is that the place has been infested by demons!\n\nMaybe you could do some preliminary work for me?\n\nThere are three locations within the ruins to the northeast where I want you to place surveying markers.  Each is near a draenei banner.\n\nReturn to me when you've managed to place all three markers.", sourceObjective = "Place the three Surveying Markers and then return to Zephyrion at the Stormspire in the Netherstorm.", progress = "That was fast.  You must be a very efficient person to have placed all three of those markers already.", completion = "You're not just pulling my bandage, right?  That's most excellent news!\n\nNow that you've done the surveying grunt-work, I'll be able to take my team up to the ruins and see what's there to be procured.\n\nYou have my thanks, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10336] = { id = 10336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Minions of Culuthas", description = "A few weeks ago, the Burning Legion moved into the Ruins of Farahlon, thwarting our plans to excavate the site for its artifacts.\n\nThen earlier today, I learned that one of their dreadlords, Culuthas, somehow killed off all of the other Burning Legion.  He has since summoned in demons that serve him.\n\n{class}, I want you to go up to those ruins to the northeast and rid them of their demon infestation.", sourceObjective = "Slay 10 Hounds of Culuthas and 5 Eyes of Culuthas.", completion = "Truly an exceptional job.\n\nWith the demons of Culuthas slain, Zephyrion will be able to safely take his excavation team into the Ruins of Farahlon.\n\nAccept this coin as a token of my gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[10337] = { id = 10337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When the Cows Come Home", description = "Realizing that Bessy is still staring at you, you gesture toward Thadell's location. You find yourself promising to protect the cow on her way home. Upon finishing your sentence, you realize there's no possible way the cow could understand anything you've said.\n\nShrugging your shoulders, you prepare to guard the bovine on her way back to Thadell.", sourceObjective = "Escort Bessy safely back to her owner, Thadell.", progress = "Have you found my Bessy?", completion = "Bessy, is that you?\n\n<The farmer turns to you.>\n\nThank you for bringing back my Bessy, {name}. I couldn't live without her!", sourceObjectiveStatus = "unverified-source-field" }
quests[10338] = { id = 10338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shutting Down Manaforge Duro", description = "So Manaforge Duro is under attack and Sunfury forces have lost control?  What a dilemma!  If Duro goes down, then Tempest Keep goes down.  Only drawback is... if Tempest Keep is destroyed, the explosion will probably take what little remains of this forsaken land with it.\n\nDead Kael'thas is good.  Dead everyone else is... not that great, I suppose.  It pains me to ask this of you, but go to Manaforge Duro and shut it down before it goes up in flames.  The access crystal is held by Overseer Athanel.", sourceObjective = "Return to Manaforge Duro and obtain the Duro Access Crystal from Overseer Athanel. Use it at the Duro Control Console to shut it down and report back to Spymaster Thalodien.\n\nPerforming quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Did you complete the shut down?  You should hurry before I change my mind about the whole deal.", completion = "That makes three manaforges you've shut down, {name}.  Kael'thas must be having a real fit right about now.", sourceObjectiveStatus = "unverified-source-field" }
quests[10339] = { id = 10339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ethereum", description = "Directly south of here you will find the Ethereum Staging Grounds. The Ethereum are there, preparing for something... Perhaps an assault on Ultris.\n\nWe can't take any chances, though, {class}. Break through their perimeter defenses and take out their training facility.\n\nOnce you've destroyed their soldiers and Captain Zovax, locate Ethereum transponder Zeta and use it to establish contact with me to get your next set of orders.", sourceObjective = "Commander Ameer wants you to kill 5 Ethereum Assassins, 5 Ethereum Shocktroopers, 2 Ethereum Researchers and Captain Zovax then activate Ethereum Transponder Zeta.", progress = "Well done, fleshling...", completion = "We must gather whatever data that they've stored in this area.", sourceObjectiveStatus = "unverified-source-field" }
quests[10340] = { id = 10340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shatter Point", description = "{name}, you've done a great job here at the front, and you showed a lot of talent with that armored gryphon... I think I have another mission in mind for you.\n\nThis new mission launches from Shatter Point -- an attack base the Wildhammers set up on a floating piece of land near the Portal.  It's a little unnerving there, but you have tough guts.  You'll be fine.\n\nTalk to Wing Commander Dabir'ee and have him send you to Shatter Point.  From there, report to the gryphon master Runetog Wildhammer.", sourceObjective = "Forward Commander Kingston wants you to speak with Wing Commander Dabir'ee, ride a gryphon to Shatter Point, and then report to Runetog Wildhammer.", completion = "Hah hah!  A fresh {race} from the mainland!  Well don't worry -- Shatter Point might make you queasy but she doesn't stray far!\n\nAnd I've only seen her flip upside down once... or twice.", sourceObjectiveStatus = "unverified-source-field" }
quests[10341] = { id = 10341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kick Them While They're Down", description = "The news you've discovered is fortunate, {name}.  Not only do you get to waltz into Manaforge Duro unfettered, this also presents a great opportunity to deal a blow to Kael's army.\n\nUse the mana creature assault to your advantage and pick off any Sunfury stragglers you run into.\n\nI do not take particular glee in the senseless slaughter of my own kin the way that Thalodien does, but the tactical advantage here is too high to pass up.", sourceObjective = "Slay 8 Sunfury Conjurers, 6 Sunfury Bowmen and 4 Sunfury Centurions. Return to Magistrix Larynna at Area 52 after completing this task.\n\nCompleting tasks for the Scryers will cause your Aldor reputation to decrease.", progress = "Have you completed your task, {name}?", completion = "You've done well, {name}.  Kael's army will not easily recover from the blow you've dealt today.", sourceObjectiveStatus = "unverified-source-field" }
quests[10342] = { id = 10342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Shaleskin Shale", description = "I make a good living selling drinks to the boozehounds around here.  But I want something more!\n\nThe rocket-chief is always telling me how he can't perfect the rocket fuel needed to get the X-52 off of the ground.\n\nWe can solve that little problem for him.\n\nFor starters I need to extract the oil from the shale of the local shaleskin flayers!  It'll form a concentrated, if explosive, base for the mix that I have in mind.\n\nFind the flayers, and their shale, all over the place near the purple rocks.", sourceObjective = "Collect 5 Shaleskin Shale and give them to Boots at Area 52 in the Netherstorm.", progress = "You have enough of that shale yet?  I'm going to need a lot of it to extract the amount of oil that'll be needed for the X-52 Nether Rocket's fuel.", completion = "OK!  Ingredient number one is down.\n\nNow, if you're up to it, we'll move on to something that'll give the shale oil that little extra kick that it'll need to blast the nether rocket into the Twisting Nether... or oblivion, whichever comes first.", sourceObjectiveStatus = "unverified-source-field" }
quests[10343] = { id = 10343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unending Invasion", description = "Kael'thas's assault on Kirin'Var began with thundering noise and a bright flash of light in the officer quarters to the northwest. The destruction there was the most severe and after the withdrawal of the blood elves, a strange thing began to happen.\n\nBeings of pure mana began streaming into the village from all over the area. For now, we're containing them as we can, but with more information about the weapon Kael'thas used, I hope to cut off the flow of mana creatures entirely.", sourceObjective = "Search the mana creature infested area of Kirin'Var Village for a Mana Bomb Fragment and bring it to Lieutenant-Sorcerer Morran.", progress = "Did you find the remains of the weapon Kael'thas used against the village?", completion = "A mana bomb?\n\n<Morran turns the fragment over in his hands.>\n\nIt's nigh unthinkable! Even the best minds in Dalaran couldn't have conceived of a weapon like this. The sheer magnitude of the disturbance must've torn a rift in the nether, giving these creatures access to our lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[10344] = { id = 10344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wing Commander Gryphongar", description = "Wing Commander Gryphongar runs this outfit of Wildhammers.  If this is your first time to Shatter Point, then you should report to him.\n\nYou'll find him inside what's left of that tower over yonder.", sourceObjective = "Speak with Wing Commander Gryphongar in Shatter Point.", completion = "You spoke with Runetog?  A fine dwarf he is.  Keeps his gryphons in good shape and battle ready.\n\nI'm Gryphongar, commander here at Shatter Point.  I know it's not pretty, but this hunk of rock is a vital staging point for sorties into Hellfire.  You'll see gryphons flying out and in non-stop!\n\nAdvice?  Here's some: keep your gear stowed, your stomach empty, and your eye on the horizon... if Shatter Point starts to teeter, then grab onto something that won't float away!", sourceObjectiveStatus = "unverified-source-field" }
quests[10345] = { id = 10345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flesh Lies...", description = "You see these corpses, {race}? Arconus is responsible for this slaughter. He's sucked them dry, leaving nothing more than a fleshy husk. But don't let the bodies fool you! Inside those corpses lie flesh beasts, waiting to pounce on the unsuspecting fool that gets too close.\n\nI've got my orders. I must remain here until backup arrives. That doesn't mean that you can't take my igniter and destroy the withered corpses that litter the mines. One way or another, the mission must be completed.", sourceObjective = "Use the Protectorate Igniter on 12 Withered Corpses. Return the Protectorate Igniter to Agent Araxes outside of Access Shaft Zeon when the task is complete.", progress = "Any luck in finding Ya-six?", completion = "You saved my wrappings, {name}. The Protectorate will know of what you've done on this day, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[10346] = { id = 10346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Abyssal Shelf", description = "{name}, you've proven yourself as a capable gryphon rider, and we could use you on more sorties over the Abyssal Shelf.  What say you, {class}?  Do you want some more flight time?", sourceObjective = "Gryphoneer Windbellow at Shatter Point in Hellfire Peninsula has asked that you destroy 20 Gan'arg Peons, 5 Mo'arg Overseers and 5 Fel Cannons.", progress = "There are still plenty of targets on the Abyssal Shelf, {name}.  Grab a gryphon when you're ready for another run.", completion = "How'd it go out there this time?  You're in pretty good shape... maybe even good enough for another run!", sourceObjectiveStatus = "unverified-source-field" }
quests[10347] = { id = 10347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Abyssal Shelf", description = "{name}, are you ready for another sortie over the Abyssal Shelf?  I fear that, if we do not maintain pressure on the Legion forces there and allow them to strengthen their hold, then we may suffer a large demon attack from the north.\n\nWhat say you, {class}?  Do you want to take another windrider and hammer the Abyssal Shelf one more time?", sourceObjective = "Wing Commander Brack at Reaver's Fall in Hellfire Peninsula has asked that you destroy 20 Gan'arg Peons, 5 Mo'arg Overseers and 5 Fel Cannons.", progress = "The Legion must not think they are safe high atop the Abyssal Shelf.  We must hit them repeatably!", completion = "The other windrider pilots speak highly of you, {name}.  You've scored quite a lot of kills on the Abyssal Shelf.  Keep up the good works!", sourceObjectiveStatus = "unverified-source-field" }
quests[10348] = { id = 10348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Opportunities", description = "I hear that a group of 'druids' from Azeroth has taken quite an interest in the effects of our eco-dome technology.\n\nThe Cenarion Expedition's representatives are eager to get access to the plants growing within the domes, particularly one called the ivory bell, known for its healing properties. They're found in clumps of brush around larger plants in Eco-Dome Midrealm.\n\nI'll share the profits with you if you're willing to gather the herbs for my first delivery.", sourceObjective = "Gather 15 Ivory Bells and return to Mehrdad at Midrealm Post.", progress = "Have you managed to gather the herbs?", completion = "Interesting choice, isn't it? The healing properties had better be miraculous. I'm charging a lot of money for a rather plain looking flower.", sourceObjectiveStatus = "unverified-source-field" }
quests[10349] = { id = 10349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Earthbinder", description = "You should take the crystal lump over to the earthbinder.  She's just like you... always needing to get to the bottom of a mystery and thinking all of the time.\n\nIf you ask me, she thinks a little too much.\n\nJust give it to her and I'm sure that she'll get you into a heap of trouble figuring out what is going on up there on the ridge.", sourceObjective = "Take the Crimson Crystal Shard to Earthbinder Galandria Nightbreeze at the Cenarion Post in Hellfire Peninsula.", progress = "Is that a piece from the giant crystal shard up on Fallen Sky Ridge?", completion = "Oh, excellent!  I've been waiting to get my hands on a piece of that thing, but Tola'thion's been dragging his feet.\n\nHe's supposed to be out here helping me to investigate what's going on up on Fallen Sky Ridge.  Instead he's just been sending poor dupes like you - no offense - up there into the slaughter mill.\n\nIf you give me the crystal maybe I can find a link between it and the colossi.", sourceObjectiveStatus = "unverified-source-field" }
quests[10350] = { id = 10350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behomat", description = "While you have learned many hard lessons from me during our time together, it is time that I entrusted you to wiser hands.\n\nBehomat, who trained me when I was as green as grass, will be your new teacher. I have told him that you will be seeking him out, and he is expecting you.\n\nYou will find him at the center of the Warriors' Terrace, at the highest point of the Traders Tier of the Exodar.", sourceObjective = "Speak with Behomat at the Traders Tier of the Exodar.", completion = "Ah, so you've finally come. I am Behomat, and I will instruct you in the ways of the {class} arts. Ruada told me of your trial against the ravager, and I am impressed. And I have a gift for you.\n\nWhat we have scavenged from the wreckage of the Exodar is little, and must be given to those most able. Please take a weapon suited to your fighting style and carry it with the knowledge you have earned it.\n\nAnd speaking of fighting styles, it's time you learned something new.", sourceObjectiveStatus = "unverified-source-field" }
quests[10351] = { id = 10351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natural Remedies", description = "It must be that the evil emanations from that giant crystal are summoning the mountain giants and driving them insane.\n\nIt's too big to move, and beyond our ability to destroy, but I know a way to quell its power.\n\nI've summoned a circle at the northwest corner of the crystal on the ridge.  Take this seed to the circle and channel its powers to heal the land through the natural forces of rain, growth and insect repopulation.\n\nBeware, {name}, I sense an external force at play here... this is not natural!", sourceObjective = "Use the Seed of Revitalization at the Earthbinder's Circle to heal the land around the crystal. Then, return to Earthbinder Galandria Nightbreeze at the Cenarion Post in Hellfire Peninsula with any information that you gain.", progress = "Did it work?  What did you learn?  Did you find out who or what is behind what happened at Fallen Sky Ridge?", completion = "Goliathon?  Pathaleon the Calculator?\n\nKAEL'THAS!?\n\nPrince Kael'thas has a hand in this?\n\n<The earthbinder fumes.>\n\nIt is insanity what he has done!  Dropping giant crystals from the sky and decimating the land can only be the work of a madman!\n\nI can assure you, the Cenarion Expedition will counter any further attempts by their forces to do this ever again.\n\nWe owe you a great debt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10352] = { id = 10352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Wool", progress = "We are currently accepting donations for wool cloth.  A donation of sixty pieces of wool cloth will net you full recognition by Darnassus for your generous actions.  Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful!  We thank you for your generous donation, {name}!" }
quests[10353] = { id = 10353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arconus the Insatiable", description = "Araxes and I were deployed to Ultris 2 days ago. Our mission: Find and terminate the void lord Arconus. We tracked him to this mine and discovered that he'd been feeding off the energies of the creatures in the area.\n\nA fire-fight broke out which resulted in Araxes and I separating. Now I'm stuck here, badly injured. The mission is in shambles!\n\nIf you can take out Arconus, high command would be grateful. Should you accept this mission, I will assist by providing a reflection of myself as a guardian.", sourceObjective = "Agent Ya-six at Access Shaft Zeon in Netherstorm has asked you to slay Arconus the Insatiable and return to Commander Ameer at the Protectorate Watch Post in Netherstorm.", completion = "And Ya-six? Did he make it?\n\nLet's damn well hope so. I was unable to get reinforcements back to them... Ethereum have the entire area covered now.\n\nMy apologies, I nearly forgot about your reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[10354] = { id = 10354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Silk", progress = "As with most other fabrics, our stocks of silk are at an all-time low.  Our stores are such that we'd only need sixty pieces of silk from you total; we should be able to reach our goal with the support of others.\n\nA benevolent gift such as silk, might I add, would certainly increase your local standing in the community!  If you have the sixty pieces of silk cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful!  We thank you for your generous donation, {name}!" }
quests[10355] = { id = 10355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Withered Flesh", description = "We must determine how far the damage has spread. The basidium you brought me comes from a bog giant. Their larger, hardier cousins, the bog lords, should prove more resistant to the degeneration that's struck the giants.\n\nIt would be good to know how the changes in the Dead Mire have affected the other creatures out there, too.\n\nReturn to the Dead Mire and see if you can get samples from the bog lords and the hydra in the area.", sourceObjective = "Gather 5 Parched Hydra Samples and 5 Withered Bog Lord Samples and bring them to Ruam at Telredor.", progress = "Were you able to gather the samples?", completion = "<Ruam examines the samples, looking distressed.>\n\nIt's exactly as I'd feared, {name}. The drying environment is taking a heavy toll on creatures never meant to live outside swampy environments. We'll have to continue to monitor the area and consult with the Cenarion Expedition to see if anything can be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[10356] = { id = 10356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Mageweave", progress = "We are currently gathering mageweave.  A donation of sixty pieces of mageweave cloth will net you full recognition by our people for your generous actions.\n\nIf you currently have sixty pieces, you may donate them now.", completion = "Our thanks for your donation, {name}." }
quests[10357] = { id = 10357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Runecloth", progress = "We are currently gathering runecloth.  A donation of sixty pieces of runecloth will net you full recognition by our people for your generous actions.\n\nIf you currently have sixty pieces, you may donate them now.", completion = "Our thanks for your donation.\n\nShould you continue to offer runecloth, I will make certain that word of your good works reaches the leaders of the Exodar." }
quests[10358] = { id = 10358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Additional Runecloth", progress = "Well met again, {name}. For an additional stack of twenty runecloth, I will make sure that you are recognized for your continuing efforts.\n\nIf you have the stack of runecloth now, I can accept the donation.", completion = "We offer thanks for your continued efforts, {name}." }
quests[10359] = { id = 10359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Wool", sourceObjective = "Give me sixty pieces of wool cloth and you will receive full recognition by Silvermoon for your generous actions.\n\nIf you have them now, I can take them.", progress = "Give me sixty pieces of wool cloth", completion = "Ah, wool cloth. I'll see to it others hear of your donation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10360] = { id = 10360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Silk", sourceObjective = "Give me sixty pieces of silk cloth and you will receive full recognition by Silvermoon for your generous actions.\n\nIf you have them now, I can take them.", progress = "Give me sixty pieces of silk cloth", completion = "Ah, silk cloth. I'll see to it others hear of your donation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10361] = { id = 10361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Mageweave", sourceObjective = "Give me sixty pieces of mageweave cloth and you will receive full recognition by Silvermoon for your generous actions.\n\nIf you have them now, I can take them.", progress = "Give me sixty pieces of mageweave cloth", completion = "Ah, mageweave cloth. I'll see to it others hear of your donation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10362] = { id = 10362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Runecloth", sourceObjective = "Give me sixty pieces of runecloth and you will receive full recognition by Silvermoon for your generous actions.\n\nIf you have them now, I can take them.", progress = "Give me sixty pieces of runecloth", completion = "Runecloth, mmm? Well, so long as you keep bringing it, I will continue to sing your praises to the people of Silvermoon.", sourceObjectiveStatus = "unverified-source-field" }
quests[10363] = { id = 10363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Additional Runecloth", progress = "For another stack of twenty runecloth, I will see to it that you are recognized for your continuing efforts on behalf of Silvermoon.\n\nSimply hand it to me when you're ready.", completion = "Well, well. Even more runecloth." }
quests[10364] = { id = 10364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caedmos", description = "You have come far in a short time, {name}. Faster than I had expected or hoped. It is time that you continued your training under the tutelage of Caedmos.\n\nI have sent word to him at the Exodar to expect you. You'll find him in the Anchorites' Sanctum near the entrance of the Vault of Lights.", sourceObjective = "Speak with Caedmos in the Vault of Lights of the Exodar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10365] = { id = 10365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shutting Down Manaforge Ara", description = "You've done much better than any of us anticipated.  Manaforge Ara is the last of Kael's working manaforges.  You'll find it northwest of here, though you're likely to have to do some circumnavigating to get to it.  We want you to shut it down.\n\nThe last access crystal is in the possession of Overseer Azarad.  This is Kael's very last source of energy as far as we know, so expect heavy opposition.  I'd bring a couple of friends along if I were you.\n\nHmm... Azarad.  What an odd name for a sin'dorei.", sourceObjective = "Travel to Manaforge Ara and obtain the Ara Access Crystal from Overseer Azarad. Use it at the Manaforge Ara console to shut it down.\n\nPerforming quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Have you completed the task I asked of you, {name}?", completion = "The Burning Legion is in cahoots with Kael?  Hah!  Voren'thal is going to have a field day with this information.\n\nDo you think the thousands of pilgrims that have come from Azeroth want to be allied with the Burning Legion?  I think not!", sourceObjectiveStatus = "unverified-source-field" }
quests[10366] = { id = 10366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jol", description = "The path of the Light and purity is not an easy one to walk, {name}. Even I, at times, struggle with following its course.\n\nYou should seek out my master, Jol, at the Exodar. She trained me when I was beginning my journey, and I believe she will find in you a new star pupil.\n\nYou will find Jol in the Vault of Lights of the Exodar at the Vindicators' Sanctum, a room surrounded by a vibrant glow of light.", sourceObjective = "Speak with Jol in the Vindicators' Sanctum of the Exodar.", completion = "{name}, I have been expecting you.\n\nTullas has sung your praises and I am eager to continue your training on the path of Light. When you are ready to unlock greater understanding of your abilities and power, I will guide you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10367] = { id = 10367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Traitor Among Us", description = "Anywhere you see a tribe of enslaved Broken you will also find a traitor.  A despicable being who sold his brothers for promises of power.\n\nThere is a hut at the top of the stairs in the center of the ruins.  That's the turncoat's hut.\n\nHe's not there right now, so you will be able to sneak in if you're patient.  Inside you will find a coffer with a key inside of it.  That key unlocks the chains that keep the Dreghood elders prisoner.  Bring it to me.\n\nBeware, Arzeth the Merciless wanders nearby.", sourceObjective = "Naladu at the Ruins of Sha'naar wants you to obtain the Sha'naar Key from a nearby hut.", progress = "Did you obtain the key, {name}?", completion = "I thank you, {name}.  My people will soon be free thanks to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10368] = { id = 10368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dreghood Elders", description = "The Dreghood spirit is broken because our elders are imprisoned.  Take this key and go downstairs to free them.\n\nThey are Morod the Windstirrer, Akoru the Firecaller and Aylaan the Waterwaker.  Once they are free, the spirits will return to the Dreghood tribe.", sourceObjective = "Free Morod the Windstirrer, Akoru the Firecaller and Aylaan the Waterwaker at the Ruins of Sha'naar. Return to Naladu after completing this task.", progress = "Tell me, {name}.  Have the Dreghood elders been released?", completion = "I can feel it, {name}!   The spirits are returning to us.", sourceObjectiveStatus = "unverified-source-field" }
quests[10369] = { id = 10369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arzeth's Demise", description = "Yes, the elemental spirits have returned to us!  We are not as strong as we once were, but a little magic can go a long way in the right hands.\n\nArzeth has great powers bestowed upon him by his dark lord.  Take this staff.  It was once a great symbol of our tribe.  Use it against Arzeth and his powers will be temporarily removed from him.  Defeat him then, so that my people may finally be free!", sourceObjective = "Use the Staff of Dreghood Elders on Arzeth the Merciless and slay him after he's lost his powers. Return to Naladu at the Ruins of Sha'naar after completing this task.", progress = "Is it done, {name}?  Is Arzeth dead?", completion = "It is true, {name}.  I was once Naladu the Keeper of Earth.\n\nIt was I who betrayed the other Dreghood elders in exchange for empty promises of power.  You can despise me now if you wish to.  What matters is that my tribe is free once again and that the spirits have returned to us.\n\nI will not be joining the rest of the tribe, but I can die in peace now.  May the spirit of earth find a new servant among my brothers.", sourceObjectiveStatus = "unverified-source-field" }
quests[10371] = { id = 10371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yorus Barleybrew", description = "A dwarven warrior known as Yorus Barleybrew has issued a challenge to all skilled Alliance warriors.\n\nHe waits at the Lakeshire Inn, in a place known as the Redridge Mountains in the Eastern Kingdoms.  The journey will be long, but it'll be worth it for you to test yourself, {name}.", sourceObjective = "Speak with Yorus Barleybrew at the Lakeshire Inn in Redridge Mountains.", completion = "Hah!  So you heard of my challenge, did you?\n\nWell sit down and listen.  Have a drink, and savor it... because it might be your last.", sourceObjectiveStatus = "unverified-source-field" }
quests[10372] = { id = 10372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Discreet Inquiry", description = "Eralan, an associate of mine in Tranquillien, has made an inquiry about securing some help for an urgent job.\n\nNow, I don't know what she has in mind because I don't ask questions, but you've proven yourself more than capable. I want you to travel to Tranquillien in the Ghostlands and have a word with Eralan.\n\nShe may be a bit gruff, but she's trustworthy.", sourceObjective = "Speak with Eralan in Tranquillien.", completion = "I was beginning to wonder if Zelanis received that letter.\n\n<Eralan nods curtly.>\n\nGood. Let's get to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[10373] = { id = 10373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Arms: The Plaguelands!", description = "Hear ye, hear ye!  All heroes are called upon to heed these words!\n\nA call to arms has been issued by the Kingdom of Stormwind!  All able bodied individuals are entreated to take up arms against the dark threat of the Scourge in the northern lands of the Eastern Kingdoms!  Rumors fly of new threats rising from the ruins of the Plaguelands!\n\nHeroes of the realm - seek out Commander Ashlam Valorfist who has set up his base camp in Chillwind Camp, north of the Alterac Mountains!", sourceObjective = "Seek out Commander Ashlam Valorfist. His base camp is located at Chillwind Camp, north of the Alterac Mountains.", completion = "Welcome to the Plaguelands, hero.  This is one of the most dangerous frontiers in Azeroth, especially with the looming threat of the Scourge to our north and northeast.  I am glad to hear that the clarion call of duty and service to the greater good did not fall on deaf ears with you!\n\nIf you are ready to get your hands dirty, then there is plenty for willing and able heroes to do here on the edge of the Plaguelands.", sourceObjectiveStatus = "unverified-source-field" }
quests[10374] = { id = 10374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Arms: The Plaguelands!", description = "Heroes of the realm, hear me - the Horde calls upon you for swift action!\n\nA call to arms has been issued for all able bodied individuals to take up arms against the Scourge!  Rumors fly of new threats rising from the ruins of the Eastern Kingdoms.  They loom to the east of the Undercity, in the northern reaches of the lands now known as the Plaguelands!\n\nHeroes of the realm - seek out High Executor Derrington, who has set up his base camp at the Bulwark, east of Tirisfal Glade!", sourceObjective = "Seek out High Executor Derrington. His base camp is located at the Bulwark, east of Tirisfal Glade and the Undercity.", completion = "Welcome to the Plaguelands, hero.  This is one of the most dangerous frontiers in Azeroth, with the looming threat of the Scourge to our east, and then even further still eastward from there.  I am glad to hear that the call of duty and service to the Horde did not fall on deaf ears with you!\n\nIf you are ready to get your hands dirty, then there is plenty for willing and able heroes to do here on the edge of the Plaguelands.", sourceObjectiveStatus = "unverified-source-field" }
quests[10375] = { id = 10375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obsidian Warbeads", description = "You've proven yourself to our people, {name}.  Now is time for you to show us that you're willing to stand by us, even in the face of the strongest enemy.\n\nThe ogres of Outland are" }
quests[10376] = { id = 10376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbol of Hope" }
quests[10377] = { id = 10377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing to Fear", sourceObjective = "You will learn:", sourceObjectiveStatus = "unverified-source-field" }
quests[10378] = { id = 10378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consume Magic" }
quests[10379] = { id = 10379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Touch of Weakness" }
quests[10380] = { id = 10380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dark Pact", description = "We've been so blind, {name}, that the alliance of two of our most dangerous enemies went completely unnoticed.\n\nI wouldn't be surprised if the Scryers had something to do with hiding this information from us, but we must now face the reality.  The Burning Legion and Kael'thas' Sunfury army serve under the same banner.\n\nThese demons are the only reason Kael'thas was ever able to utilize the technology in Tempest Keep.  Under Orelis's orders I must command you to destroy them.", sourceObjective = "Kaylaan at Tuluman's Landing in Netherstorm wants you to slay 6 Gan'arg Warp-Tinkers, 3 Daughters of Destiny and 3 Mo'arg Warp-Masters.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you succeeded in your task, {name}?", completion = "It is done then.  We come here, hunt them down and slay them at the bidding of our masters.  No quarter is given or expected.\n\nMakes you wonder sometimes.", sourceObjectiveStatus = "unverified-source-field" }
quests[10381] = { id = 10381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aldor No More", description = "My mission here is finished.  I did what Orelis ordered me to - I've never failed to.\n\nNo more.  I foresee a great carnage - a crusade, they'll call it - following the news of this alliance between Kael'thas and the Burning Legion.\n\nFirst they give our holiest city away to our enemies and then they ask us to die fighting their enemies.  Go back to Orelis; tell him the naaru can fight their own fights from now on.", sourceObjective = "Report back to Exarch Orelis at Area 52.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", completion = "The bad news you bring fills my heart with sorrow.  Two of our deadliest foes join forces and one of the dearest sons of Shattrath has lost his way.", sourceObjectiveStatus = "unverified-source-field" }
quests[10382] = { id = 10382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go to the Front", description = "Well, {name}, I hope you're prepared for the next phase of our operation. The Legion never rests - and neither shall we! Take a gryphon and fly over to Honor Point - it's a small post near the Legion Front. \n\nSpeak with Field Marshal Brock. He'll have instructions for you when you arrive. Oh, and tell that pasty-faced shield-kisser I said 'hello'.", sourceObjective = "Take a gryphon to Honor Point and speak with Field Marshal Brock.", completion = "Well met, {class}. I'm glad that crusty old dwarf finally saw fit to send us some help!", sourceObjectiveStatus = "unverified-source-field" }
quests[10383] = { id = 10383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This is a Breadcrumb!", description = "Hello.  You should find out about those wabbits.", sourceObjective = "Speak with Jonathan LeCraft about the wabbits.Hello. You should find out about those wabbits.", sourceObjectiveStatus = "unverified-source-field" }
quests[10384] = { id = 10384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ethereum Data", description = "Look around you, fleshling. Very close to this transponder should be an Ethereum data cell. Locate that data cell, open it, and retrieve the contents.\n\nBring it back to this transponder at once!", sourceObjective = "The Image of Commander Ameer at the Ethereum Staging Grounds - Ethereum Transponder Zeta - wants you to recover the Ethereum Data Cell.", progress = "Have you recovered the data cell?", completion = "<You hold the data cell out so Ameer can read the plans.>\n\nNothing... Damn them! They're clever but not as clever as Ameer!\n\nWhat I'm about to ask you to do is quite dangerous. I'll understand if you don't want to continue, fleshling.", sourceObjectiveStatus = "unverified-source-field" }
quests[10385] = { id = 10385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potential for Brain Damage = High", description = "They're using relays to transfer information around the staging grounds.\n\nThere is only one way for you to see these relays and extract the information they hold. Unfortunately, doing so may cause you irreparable brain damage.\n\nIf you're still interested, you'll need to slay Ethereum here at the staging grounds and take their essences. Once you have an essence, drink it down. It will temporarily allow you to see an Ethereum relay - giving you enough time to destroy a relay and extract its information.", sourceObjective = "The Image of Commander Ameer at the Ethereum Staging Grounds - Ethereum Transponder Zeta - wants you to recover 15 pieces of Ethereum Relay Data.", progress = "Have you recovered the relay data?", completion = "The Protectorate's reason for existence is now fully realized.\n\nThe Ethereum are not here to hunt Dimensius! They are here to become void!\n\nThey are manipulating the void energy at this manaforge to bond their own energy into a creature known as a nexus-stalker.\n\nThey are undoubtedly using a proto-accelerator to complete the transformation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10386] = { id = 10386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fel Reaver Slayer", description = "Overlord Hun Maimfist is always looking for volunteers for his suicide attacks against the Burning Legion.  You definitely have the courage for one of his \"missions.\"  \n\nSpeak with him if you've got the stomach for more carnage.  He is celebrating just over there by that fallen fel reaver.  He and his guards killed it just a few hours ago, we would all have died here but for his ferocity and skill in battle.", sourceObjective = "Speak with Overlord Hun Maimist.Overlord Hun Maimfist is always looking for volunteers for his suicide attacks against the Burning Legion. You definitely have the courage for one of his \"missions.\"  \n\nSpeak with him if you've got the stomach for more carnage. He is celebrating just over there by that fallen fel reaver. He and his guards killed it just a few hours ago, we would all have died here but for his ferocity and skill in battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[10387] = { id = 10387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fel Reaver Slayer", description = "Overlord Hun Maimfist is always looking for volunteers for his suicide attacks against the Burning Legion.  You definitely have the courage for one of his \"missions.\"  \n\nSpeak with him if you've got the stomach for more carnage.  He is celebrating just over there by that fallen fel reaver.  He and his guards killed it just a few hours ago, we would all have died here but for his ferocity and skill in battle.", sourceObjective = "Speak with Overlord Hun Maimist.Overlord Hun Maimfist is always looking for volunteers for his suicide attacks against the Burning Legion. You definitely have the courage for one of his \"missions.\"  \n\nSpeak with him if you've got the stomach for more carnage. He is celebrating just over there by that fallen fel reaver. He and his guards killed it just a few hours ago, we would all have died here but for his ferocity and skill in battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[10388] = { id = 10388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Thrallmar", description = "Hope you enjoyed your flight, friend. A messenger arrived while you were away - seems Nazgrel's got a new use for you. You'd best head back to Thrallmar and check in with him. I have a feeling the Legion's just getting warmed up.", sourceObjective = "Return to Thrallmar and speak with Nazgrel.", completion = "Ah, {name}, you've come just in time. Our scouts have discovered that the Legion positions on the ridge behind us are actually 'forge camps'. It's there that the demons are constructing their infernal fel reavers. If we move against them quickly we can disrupt their production!", sourceObjectiveStatus = "unverified-source-field" }
quests[10389] = { id = 10389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Agony and the Darkness", description = "Greetings, {name}. I've deciphered the Legion missive and uncovered the demons' strategic plans for this Peninsula. Apparently, there is a large group of hellish terrorfiends gathering near the Pools of Aggonar in the west. We cannot allow such a force to go unchallenged. You must go there and decimate their cursed numbers.", sourceObjective = "Magister Bloodhawk wants you to kill 10 Terrorfiends in the Pools of Aggonar.", progress = "Well, {class} - have the terrorfiends been defeated?", completion = "Bravo, {name}. I knew you would be victorious! The Legion's defeat draws ever nearer!", sourceObjectiveStatus = "unverified-source-field" }
quests[10390] = { id = 10390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forge Camp: Mageddon", description = "{name}, we have reason to believe that the easternmost forge camp is not yet complete. The Legion's gan'arg servants are working 'round the clock to get the facility up and running. We can't allow that to happen. \n\nHead east to Forge Camp: Mageddon and slay 10 gan'arg. Bring me the head of their master - Razorsaw - and the Legion's fel reaver production will grind to a halt!", sourceObjective = "Nazgrel in Thrallmar wants you to attack Forge Camp: Mageddon and kill 10 Gan'arg Servants and return with the head of Razorsaw.", progress = "Move quickly, {class}, we've got to shut down Forge Camp: Mageddon before the demons finish its construction!", completion = "Well done, {class}, That's one less forge camp we'll need to worry about. It'll take the Legion a while to get that facility back up and running. You've just bought us the one thing we'd run out of - time.", sourceObjectiveStatus = "unverified-source-field" }
quests[10391] = { id = 10391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cannons of Rage", description = "There is a second production facility, Forge Camp: Rage, that lies to the immediate northeast of Thrallmar. The demons have positioned a number of their fel cannons along the ridge - and they're aimed straight at us! You must enter the camp and destroy these fel cannons. \n\n{name}, you must be sure to detonate them all - or nothing will stop the Legion from raining fiery hell down upon our heads!", sourceObjective = "Destroy 3 Fel Cannon MKIs in Forge Camp: Rage and return to Nazgrel in Thrallmar.", progress = "The Legion could start shelling us at any time, {name}! You need to destroy those blasted cannons!", completion = "I knew you had spirit, {name}, but you've outdone yourself this time! We heard those wretched cannons exploding from here! That should teach the Legion not to underestimate the Sons of Durotar!", sourceObjectiveStatus = "unverified-source-field" }
quests[10392] = { id = 10392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doorway to the Abyss", description = "You are an honor to us, {name}. But now we must strike before the Legion recovers! To the north of Thrallmar lies Invasion Point: Annihilator. It houses a warp-portal through which the Legion draws its reinforcements. \n\nYou must overload that portal - and blast it back to the abyss it came from. The portal's activation key will be held by the Point's commander - Warbringer Arix'Amal. Slay him. Take the key. Use it on the portal and do what must be done. May the warchief's blessings be with you.", sourceObjective = "Slay Arix'Amal to get the Burning Legion Gate Key. Use the Burning Legion Gate Key on the Rune of Spite, then return to Nazgrel in Thrallmar.", progress = "Hurry, {name}. Every second that warp-portal stands open, another foul demon is brought into this world!", completion = "Praise the ancients, you've done it, {name}! The Legion has suffered a terrible defeat - and Thrallmar is safe once again. Ah, if I had but a hundred warriors with your heart and cunning, this broken land would be tamed already! I salute you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10393] = { id = 10393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile Plans", description = "The text on the note is written in some dark, indecipherable scrawl. The more you stare at them, the more the symbols seem to twist and burn before your eyes. There is only one in Thrallmar that can transcribe such vile script - the blood elf Magister Bloodhawk.", sourceObjective = "Take the Burning Legion Missive to Magister Bloodhawk in Thrallmar.", progress = "I have little time to waste, {class}. What is this you pester me with?", completion = "You were right to bring this to my attention. This could be a production order for additional fel reavers - or new attack plans! This will take some time to decipher. Leave me. I will summon you when I know more. \n\n<Magister Bloodhawk nods to you as you turn to leave> \n\nYou are a sharp one, {name}. I shall be watching your progress with interest.", sourceObjectiveStatus = "unverified-source-field" }
quests[10394] = { id = 10394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disruption - Forge Camp: Mageddon", description = "Pay close attention, {name}. We've been surveying the Legion camps that lie along the ridge ahead. We have reason to believe that these so-called 'Forge Camps' are where the demons are constructing those blasted Fel Reavers. \n\nYou can see the closest target, Forge Camp: Mageddon, to the west. Our intelligence suggests that it's still under construction. If you can slay the Gan'arg Servants and their master - Razorsaw - we can bring the Legion's Fel Reaver production to a grinding halt!", sourceObjective = "Kill 10 Gan'arg Servants and Razorsaw at Forge Camp Mageddon and return to Forward Commander Brock at Honor Point.", progress = "Don't tell me your getting cold feet, {class}? If they finish construction on that Forge Camp, you'll have more to worry about than just those Fel Reavers! Get to it!", completion = "Well, I must say, I am impressed, {name}. I didn't think you had the mettle for this mission. Well done. Well done, indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[10395] = { id = 10395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Missive", description = "The text on the note is written in some dark, indecipherable scrawl. The more you stare at them, the more the symbols seem to twist and burn before your eyes. There is only one at Honor Hold who can decipher such archaic script - the draenei mystic, Kryv. \n\nTake the Burning Legion Missive to Warp-Scryer Kryv who resides within the War-Room at Honor Hold.", sourceObjective = "Take the Missive to Warp-Scryer Kryv in the main keep of Honor Hold.", progress = "What is it, {class}? I sense you've found something that speaks of a coming doom.", completion = "It is fortuitous that you intercepted this missive when you did, {name}. Though it will take me some time to decipher, I can already sense the hatred and urgency woven into this scroll. I fear the Legion's true motives in this land will soon be made evident...\n\nGive me a moment to decipher this script.", sourceObjectiveStatus = "unverified-source-field" }
quests[10396] = { id = 10396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemy of my Enemy...", description = "Now we focus on the second target - Forge Camp: Rage. It lies just west of Mageddon. Trouble is, the demons have a number of fel cannons aimed straight at the Horde's outpost of Thrallmar! Though I can scarcely believe it, we actually need the Horde to help us hold the line at the Dark Portal. We can't afford to let Thrallmar fall.  You've got to destroy these cannons before the Legion pulverizes our allies!", sourceObjective = "Destroy 3 Fel Cannon MKIs in Forge Camp: Rage and return to Field Marshal Brock at Honor Point.", progress = "The Legion could start shelling the Horde at any time, {name}! You need to destroy those blasted cannons!", completion = "I have to hand it to you, {name}, you're a fighter born! Those Horde yokels may never know how close they came to the end. It takes real character to step in harm's way on behalf of your enemies. That's the kind of honor and commitment that holds the Alliance together!", sourceObjectiveStatus = "unverified-source-field" }
quests[10397] = { id = 10397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion Point: Annihilator", description = "Well, we've located the Legion's final base on the ridge - Invasion Point: Annihilator. It lies northwest of Forge Camp: Rage - and it houses a warp-portal through which the Legion has been drawing its reinforcements! \n\nYou've got to close that portal to prevent any more demons from coming through. The Point's overlord, Warbringer Arix'Amal, holds the portal's activation key. Take it from him and shut that blasted gateway down!", sourceObjective = "Slay Arix'Amal. Take the Burning Legion Gate Key. Use the Burning Legion Gate Key on the Rune of Spite.", progress = "You close down that war-portal yet, {name}? While you're here shuffling your feet, there are more demons entering Outland!", completion = "Great job! That should drastically cut down on the number of demons trying to creep up our backsides. I can't thank you enough for your help out here, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10399] = { id = 10399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of Darkness", description = "It is just as I feared. Arix'Amal - the demon you killed earlier, was working for a secret Legionlord - Arazzius the Cruel. It appears this new villain has amassed a force of hellish terrorfiends near the Pools of Aggonar. \n\nYou must journey there and slay the terrorfiends before they strike against us. But be wary, friend - the Pools of Aggonar lie within a tortured, poisonous valley. You can find the cursed pools to the northwest of here, beyond Hellfire Citadel. \n\nLight be with you, {name}.", sourceObjective = "Kill 10 Terrorfiends in the Pools of Aggonar and return to Warp-Scryer Kryv in the main keep of Honor Hold.", progress = "I sense a growing darkness within your heart, {class}. Have you faced your fear? Or does it still await you at the Pools of Aggonar?", completion = "I foresaw this great victory, {name}. The blessed naaru smile upon you this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[10400] = { id = 10400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overlord", description = "The honorable Warp-Scryer has told me of your perils, {name} - and of the new foe you've discovered. If Kryv is to be believed, this 'Arazzius the Cruel' is as powerful and evil as any foe the Sons of Lothar have ever faced. \n\nWill you stand for us now, {name}? Will you face this Legionlord and deliver the Light's justice upon him? If so, you will find him at the Pools of Aggonar. If not, his evil will most certainly find you.", sourceObjective = "Slay Arazzius the Cruel in the Pools of Aggonar and return to Force Commander Danath Trollbane in the keep of Honor Hold.", progress = "Tell me, {name}, has the deed been done? Has the Legionlord been vanquished?", completion = "Light be praised, I knew you'd do it! Arazzius and his minions are no more! Soon, we'll have the Legion running for home and this battered world will be safe once more. Then, when justice has been met, we can return home as well. \n\nThanks you, {name} - the Alliance and the Sons of Lothar honor you this day!", sourceObjectiveStatus = "unverified-source-field" }
quests[10403] = { id = 10403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naladu", description = "Perhaps not all hope is lost for the Dreghood.  I am one of four elders that guided this tribe before we were enslaved by the Illidari.  I thought the others were dead, but I've slowly learned that at least two others are alive - chained down and powerless just as I am.\n\nI've not yet been able to find Naladu and fear for the worst.  There are more huts in the ruins upstairs; perhaps you could look for him.  It would be a great boon for our tribe if all our elders were alive.", sourceObjective = "Seek out Naladu inside the Ruins of Sha'naar.", completion = "You've come to help my tribe, {race}?  How unusual.  There aren't many that care about the fate of the Broken in this land.", sourceObjectiveStatus = "unverified-source-field" }
quests[10404] = { id = 10404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against the Legion", description = "We've established that the Burning Legion has been providing Kael'thas with technological assistance, magnifying his threat many times over.\n\nBased on the Legion's numbers in the region, the largest impact we can make on our enemy's alliance is through a head-on attack on the forge bases to the north.\n\nGo to Forge Base: Oblivion and Forge Base: Gehenna and destroy our enemies.  May the Light guide your blade, {name}.", sourceObjective = "Exarch Orelis at Area 52 wants you to go to Forge Base: Oblivion and Forge Base: Gehenna and slay 12 Gan'arg Forgehands, 6 Mo'arg Forgelords and 6 Wrathbringers.\n\nPerforming quests for the Aldor will cause your Scryers reputation to decrease.", sourceObjectiveStatus = "unverified-source-field" }
quests[10405] = { id = 10405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "S-A-B-O-T-A-G-E", description = "We must destroy the machinery that is making these nexus-stalker aberrations possible. To strike at their proto-accelerator would be futile as it is an ethereal creation. We must instead destroy the manaforge energy tube that they are using as a conduit.\n\nI have all that I need to create a device to overload the conduit save for one item. I need a wrapping from an archon or overlord that might be transforming soon in order to calibrate the device.", sourceObjective = "The Image of Commander Ameer at the Ethereum Staging Grounds - Ethereum Transponder Zeta - wants you to recover 1 Prepared Ethereum Wrapping.", progress = "Have you recovered the wrapping?", completion = "Excellent! Now to calibrate the device.", sourceObjectiveStatus = "unverified-source-field" }
quests[10406] = { id = 10406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivering the Message", description = "I'm sending one of my demolitionists out to place the disruption device. Just make sure no harm comes to him as he's placing the disruptor.\n\nKeep him protected! He will not fight back if enemies attack him as he is only a holographic image but the image can be destroyed!\n\nReturn to me once the job is done.", sourceObjective = "The Image of Commander Ameer at the Ethereum Staging Grounds - Ethereum Transponder Zeta - wants you to escort the Protectorate Demolitionist to the Manaforge Ultris conduit and keep him protected while he works to sabotage the pipeline.", progress = "He must succeed!", completion = "Thanks to you, their plans are in ruin! Now only one thing remains... Salhadaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10407] = { id = 10407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Socrethar's Shadow", description = "The infamous eredar, Socrethar, leads the Burning Legion in Netherstorm.  Mentioning his name is enough to make most draenei shudder.  He gives orders from an island in the northwest that only his most trusted lieutenants can access.\n\nTo get there you will need to obtain a teleportation stone, which won't be an easy task.  The first half of the stone is in the possession of Forgemaster Morug at Forge Base: Oblivion.  The second half is held by Silroth at Forge Base: Gehenna.", sourceObjective = "Anchorite Karja at Area 52 wants you to obtain the First Half of Socrethar's Stone from Forgemaster Morug at Forge Base: Oblivion and the Second Half of Socrethar's Stone from Silroth at Forge Base: Gehenna.\n\nPerforming quests for the Aldor will cause your Scryers reputation to decrease.", progress = "Have you obtained Socrethar's teleportation stone, {name}?", completion = "Your dedication to our cause is exemplary, {name}. With Socrethar's teleportation stone in our possession only one thing remains to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[10408] = { id = 10408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nexus-King Salhadaar", description = "I have in my possession another disruptor, one capable of destroying the three conduits that surround Salhadaar. Once the conduits are destroyed, Salhadaar's protective force fields will be down. For this act, he will strike at you with a ferocity you have never before witnessed, {name}.\n\nIf you are willing to rid the world of Salhadaar, I will give you the disruptor.", sourceObjective = "The Image of Commander Ameer at the Ethereum Staging Grounds - Ethereum Transponder Zeta - wants you to use the Protectorate Disruptor to bring down Salhadaar's force fields and then destroy Nexus-King Salhadaar.", progress = "Is... Is he really dead? Destroyed?", completion = "It has been a thousand years, maybe more, since Salhadaar began his crusade to exterminate all that would stand in his way. I can hardly believe that this is the last we'll see of him... You have done all of us a great service, {name}, and for that you will be rewarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[10409] = { id = 10409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deathblow to the Legion", description = "When facing eredar of great power, large armies are useless for the most part.  Their corruptive powers over mortal souls are such that only the strongest-willed can even stand face to face with them.\n\nTake this stone to the Invasion Point: Overlord, between Forge Base: Oblivion and Gehenna and bring your closest, strongest friends with you.  Orelis and Karja will meet you at Socrethar's Seat; I will send Adyen along with them.\n\nMay the Light prevail today, {name}.  May Socrethar meet his end.", sourceObjective = "High Priestess Ishanah wants you to go to the Legion Teleporter at the northwestern corner of Netherstorm and use it to teleport to Socrethar's Seat. Once there, defeat Socrethar.\n\nPerforming quests for the Aldor will cause your Scryers reputation to decrease.", progress = "Light be with you, {class}.", completion = "It is done, {name}.  Socrethar has been destroyed.\n\nI and the others will recover from our wounds, {name}.  The wrath of Socrethar's magic was far too much for young Kaylaan, however.  Not even my strongest prayer could raise him.\n\nIt is an unbearable pity that one so young would fall in battle.  However, in the end his will was strong enough to recover from the Legion's corruption and we may find solace in that.", sourceObjectiveStatus = "unverified-source-field" }
quests[10410] = { id = 10410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ishanah's Help", description = "The time has come to face Socrethar, {name}.  Confronting an eredar leader isn't something that's taken lightly among us.  A single mistake is likely to cost us our lives if we're ill-prepared.\n\nTake Socrethar's teleportation stone to High Priestess Ishanah at the Shrine of Unending Light in Shattrath City.  She will determine how we need to handle the situation.", sourceObjective = "Take Socrethar's Teleportation Stone to High Priestess Ishanah at the Shrine of Unending Light on the Aldor Rise in Shattrath City.\n\nPerforming quests for the Aldor will cause your Scryers reputation to decrease.", progress = "What troubles you, child?", completion = "Socrethar... I remember that name.  He was once a renowned warrior of the Light and pride was his only flaw.", sourceObjectiveStatus = "unverified-source-field" }
quests[10411] = { id = 10411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Electro-Shock Goodness!", description = "Around the ruined manaforge you will find the run-off of Dimensius's handy work. Seeping sludge occupies the pools that surround Ultris. Directly below those pools, where the Ethereum Staging Grounds now stand, you will find even more run-off in the form of void waste.\n\nThe best method of disposal is to use electro-shock to break slimes down to globules. Use this elixir to augment your attacks with electricity. The resultant discharge will break the slimes up into their raw form. Destroy the globules!", sourceObjective = "Researcher Navuud at the Protectorate Watch Post in Netherstorm has asked that you destroy 30 Void Waste Globules and 30 Seeping Sludge Globules.", progress = "Both the sludge and waste are extremely toxic. They will form into a congealed void horror if left unchecked!", completion = "I hope it's not too late. Did you notice any abnormally large slimes at or near the area where the void wastes drain into?", sourceObjectiveStatus = "unverified-source-field" }
quests[10412] = { id = 10412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firewing Signets", description = "It is no secret that Kael'thas Sunstrider perceives us as a great threat.  Let's face it - not many sin'dorei, fresh from Silvermoon, are willing to join the sort of company that Kael keeps.\n\nIt's also no secret that this is not just a war of words.  Scryers and the armies that serve Kael'thas attack each other on sight.  The only way to prove you're with us, {name}, is to do your share of fighting.\n\nKael's lower ranking followers wear Firewing signets to indicate their rank.  Bring them to me.", sourceObjective = "Magistrix Fyalenn in Shattrath City wants you to bring her 10 Firewing Signets.\n\nPerforming quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Go on, {name}.  Speak.", completion = "Well done, {name}.  You might prove to be a useful ally after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[10413] = { id = 10413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horrors of Pollution", description = "You carefully fill a vial with the fallen void horror's ooze.\n\nResearcher Navuud at the Protectorate Watch Post would be quite interested in such a find! Take it to him at once!", sourceObjective = "Take the Vial of Void Horror Ooze to Researcher Navuud at the Protectorate Watch Post in Netherstorm.", progress = "Hrm, you look a bit dirty... What have you gotten yourself into?", completion = "WHAT!? You faced off against a void horror? And lived?! Incredible!\n\nThis sample is worth its weight in gold. A find like this deserves a reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[10414] = { id = 10414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Single Firewing Signet", progress = "Even the smallest contribution to our cause is noted, {name}.  Our enemies are many, but we shall prevail!", completion = "Yes... Kael's numbers continue to dwindle as our numbers continue to grow.\n\n<This quest can be repeated up to Honored reputation.>" }
quests[10415] = { id = 10415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Firewing Signets", progress = "What have you done for us lately, {name}?  The war against Kael'thas is not going to fight itself, you know?", completion = "Excellent!  All who oppose us will be crushed!\n\n<This quest can be repeated up to Honored reputation.>" }
quests[10416] = { id = 10416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Synthesis of Power", description = "Arcane tomes are not ordinary books that happen to deal with arcane matters.  There is intrinsic power in them - a power I've learned to synthesize into a single arcane rune.\n\nShould you find an arcane tome in your travels I will give you one such rune.  Only the most powerful wielders of magic carry the books I need.  In Outland this usually means Kael's blood elves - but you'd be surprised by where such tomes often turn up.", sourceObjective = "Voren'thal the Seer in Shattrath City wants you to obtain an Arcane Tome.\n\nPerforming quests for the Scryers will cause your Aldor reputation to decrease.", progress = "Have you obtained an arcane tome yet, {name}?", completion = "As promised, {name}.  The entirety of the book's raw power, condensed into a single rune.", sourceObjectiveStatus = "unverified-source-field" }
quests[10417] = { id = 10417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Run a Diagnostic!", description = "Wherever the Consortium establishes a presence, we bring our eco-dome technology. The fields allow us to work in a controlled and life-sustaining atmosphere since we often find ourselves in hostile environments.\n\nNetherstorm's volatile conditions and creatures have begun to destroy the equipment that sustains our domes, especially the generator east of here. I've started a diagnostic there in hopes of understanding what can be done to combat the damage. Would you collect the results and bring them to me?", sourceObjective = "Retrieve the Diagnostic Results and return them to Mehrdad at Midrealm Post.", progress = "Did you get the diagnostic results?", completion = "<Mehrdad nods, then examines the diagnostic results.>\n\nThis is worrisome. The damage is much more severe than I believed. I can send to the Stormspire for some tools to begin repairs, but that's useless unless we've isolated what's damaging the equipment in the first place.", sourceObjectiveStatus = "unverified-source-field" }
quests[10418] = { id = 10418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deal With the Saboteurs", description = "In searching the area for clues about the damage to our equipment, I've seen pieces of the shield generators at the bottom of the small lake to the north. I'm not sure why the crocolisks have taken an interest in the equipment, but we have to put a stop to this problem.\n\nThe Consortium is quite clear on this matter. If it comes down to a choice between the equipment and crocolisks, the animals will have to go. I'll make it worth your while to deal with them.", sourceObjective = "Mehrdad at Midrealm Post wants you to kill 8 Barbscale Crocolisks.", progress = "Have you put the creatures out of their misery? Don't get me wrong, I'm really an animal lover, but not when the animals are biting the hand that feeds and shelters them.", completion = "The area's looking clearer already. The domes are quite useful, but the major drawback is the rampant growth they encourage in some places, accelerating the growth and proliferation of native species.", sourceObjectiveStatus = "unverified-source-field" }
quests[10419] = { id = 10419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Tomes", progress = "Have you obtained any more arcane tomes, {name}?", completion = "The power contained in this tome is tremendous.  Yet it is easily condensed into a single rune by one with a clear mind." }
quests[10420] = { id = 10420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cleansing Light", description = "This temple is one of the holiest places in all of Outland.  The power of the Light here is so strong, that even items with the strongest fel taint can be cleansed of a worldly item.\n\nShould you run into any fel armaments in your confrontations with demonic enemies, bring them to me and I will demonstrate the cleansing power of the Light.", sourceObjective = "Bring a Fel Armament to Ishanah in Shattrath City.\n\nCompleting quests for the Aldor will cause your Scryers reputation to decrease.", progress = "Have you obtained any fel armaments yet, {name}?", completion = "Watch as foul materials disintegrate.  Watch as metal turns to dust.\n\nThe Light cleanses all and only the purest residue remains.", sourceObjectiveStatus = "unverified-source-field" }
quests[10421] = { id = 10421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Armaments", progress = "Have you run into any fel armaments lately?  Let the Light do its work, {name}.  Do not allow these foul objects to remain in this world.", completion = "The fel materials are removed from this world.  Only the Light's residue remains." }
quests[10422] = { id = 10422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Tyralius", description = "Captain Tyralius took a platoon of soldiers south towards the Ethereum Staging Grounds 10 days ago. We haven't heard from him or his crew since.\n\nChances are good that they were ambushed and killed but I'm getting a curious reading from my instruments.\n\nI think it's a distress signal but these things have been wrong before. If Tyralius is still alive, they're keeping him in one of their prisons. You'll have to locate the prison and open it with a key, probably found on the warden.", sourceObjective = "Flesh Handler Viridius at the Protectorate Watch Post in Netherstorm has asked that you find and free Captain Tyralius.", progress = "Did you find Tyralius?", completion = "Thank you, {name}. Tyralius suffered massive injuries but we think he's going to make it.\n\nHe mentioned fields of prisons, much like the one you rescued him from. Prisons full of creatures from all across the universe!\n\nWe'll be in touch should a need arise to crack those open. The Consortium has already expressed some interest in sending some teams out and is working on some technology to break through the Ethereum's locks.", sourceObjectiveStatus = "unverified-source-field" }
quests[10423] = { id = 10423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Stormspire", description = "Master Engineer Ghabar will want to know about the results of the diagnostics. If anything, they caution us to keep a close eye on the workings of our dome generators. As the fields become more and more unstable, their effects will become harder to control. It could spell disaster for our expedition and anything else housed within the domes.\n\nYou'll find Ghabar at the Stormspire. Just follow the road north from this eco-dome and across the bridge. It'll lead you to the elevator at the base of the spire.", sourceObjective = "Speak with Ghabar at the Stormspire in Netherstorm.", completion = "<You introduce yourself and report the results of Mehrdad's diagnostics at Eco-Dome Midrealm.>\n\nMehrdad is little more than a technician, but he possesses a keen eye for detail. If his observations are correct, then we'll need to take diagnostics at the rest of our dome generators as soon as possible.", sourceObjectiveStatus = "unverified-source-field" }
quests[10424] = { id = 10424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diagnosis: Critical", description = "If Mehrdad's results are correct -- and I have no reason to believe they're faulty -- then the rest of the domes could be in trouble.\n\nI do think Mehrdad has failed to identify the underlying cause of the failures. From time to time, creatures damage the generators, but never this severely.\n\nTo be on the safe side, I'd like for you to run a set of diagnostics at the Stormspire's main dome generator, located in Eco-Dome Sutheron at the very eastern edge of the dome.", sourceObjective = "Use the Diagnostic Device while standing near the Eco-Dome Sutheron Generator and bring the Diagnostic Results back to Ghabar at the Stormspire.", progress = "Did you get those diagnostics?", completion = "These results match Mehrdad's exactly, but why? The only possible explanation I can think of is that some of the dome generation equipment has failed or gone missing. That would cause the domes to weaken significantly and fall out of balance as the diagnostics indicate.", sourceObjectiveStatus = "unverified-source-field" }
quests[10425] = { id = 10425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from the Staging Grounds", description = "Thank K'aresh! He would have torn me apart!\n\nI'm a Protectorate soldier, fleshling. My platoon was sent on a recon mission about 10 days ago. As we were moving across the upper ledges of this island, a group of Ethereum jumped us. At least I think it was Ethereum. They had the same energy color but their wrappings looked void.\n\nOnly Tyralius was spared. I think they put him in a prison cell.\n\nI've got to get back to the Protectorate Watch Post! Can you escort me back?", sourceObjective = "Escort the Captured Protectorate Vanguard back to Protectorate Watch Post in Netherstorm.", progress = "Yes?", completion = "<Commander Ameer appears pleased.>\n\nWell done, fleshling! This soldier might be the key to taking down the Ethereum's entire operation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10426] = { id = 10426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flora of the Eco-Domes", description = "Just look around you, {class}! Isn't it amazing? Of course, this incredible resurgence of life is a byproduct of the ethereal domes, but imagine what it could do in the hands of the expedition.\n\nI'm preparing to negotiate with the ethereals for access to their technology, but I'd like to get a better idea of its effects on plant-based life.\n\nI've built a device to concentrate the dome's energies on the lashers in this area. Would you be so kind as to test it for me and share the results?", sourceObjective = "Use the Energy Field Modulator on Farahlon Lashers. Observe the results and report back to Aurine Moonblaze at the Stormspire when you have conducted 10 tests.", progress = "Did you try focusing the dome's energy?", completion = "Oh my! Focusing the dome's energy seems to continue accelerating growth to the point where it breeds extreme aggression. If we do get the ability to use this technology, we have to be sure to calibrate it correctly.", sourceObjectiveStatus = "unverified-source-field" }
quests[10427] = { id = 10427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creatures of the Eco-Domes", description = "Your work with the lashers turned up some astounding information, but I wonder if it holds true for animals as well.\n\nGathering information on the talbuks that live underneath this dome is going to be trickier than studying the lashers, I'm afraid.\n\nUsing this tagging device, you can put a weakened talbuk to sleep and apply a tag that I'll use to track the animal as it matures. The tagging mechanism won't work unless the talbuk has expended most of its energy.", sourceObjective = "Tag 12 Talbuks for Aurine Moonblaze at the Stormspire. You may tag either Talbuk Sires or Talbuk Does using the Talbuk Tagger.", progress = "Were you able to tag enough of the talbuk?", completion = "Excellent work. I'll keep a close eye on the ones you tagged and see if they mature as quickly as the other lifeforms in the dome.\n\nWith the proper control, we could use this technology to regrow the ruined areas of Outland and Azeroth.", sourceObjectiveStatus = "unverified-source-field" }
quests[10428] = { id = 10428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Fisherman", description = "In the fevered dreams of our injured guest, she spoke of a fisherman, Cowlen, who was in some distress at Silvermyst Isle, to the southwest, off the coast of Azuremyst.\n\nWith all that has been happening, no one has had the opportunity to look into it, but I do feel a bit of worry. Perhaps there's something you can do, {name}?", sourceObjective = "Find Cowlen at the southeast docks of Silvermyst Isle off the coast of Azuremyst.", completion = "My family... What have I done... What could I have done?\n\nWhy must I be punished so?", sourceObjectiveStatus = "unverified-source-field" }
quests[10429] = { id = 10429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Nature Goes Too Far", description = "The dome technology possesses such power! Certainly, there are bounds beyond which we dare not go, {name}.\n\nCreatures allowed to grow too large or too fast could be just as bad as a barren landscape.\n\nI have heard rumors of just such a creature in the pool to the east. I've heard the ethereal merchants conspiring to catch the overgrown hydra for sport, but I have another purpose in mind for the giant. Bring me the creature's heart so I may study it.", sourceObjective = "Aurine Moonblaze at the Stormspire wants you to bring her a Hulking Hydra Heart.", progress = "Did you get the sample from the monstrous hydra?", completion = "<Aurine accepts the heart.>\n\nEven for a creature of that size, this heart is far too large. It struggled to keep up with the creature's gigantic body. I have little doubt it would've died before reaching half its normal lifespan.\n\nEven with such risks, I'm determined to convince the Consortium to share their technology. There's too much promise here to give up now.", sourceObjectiveStatus = "unverified-source-field" }
quests[10430] = { id = 10430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing the Prototype", description = "I've been working on a portable generator repair kit for use in some of the harsher climates that the Consortium operates in. Granted, it wasn't designed for Netherstorm, but we shouldn't have any problems with it.\n\nI had already scheduled a test with one of my best techs up at Eco-Dome Farfield beyond the Netherstone to the northeast. Take this prototype to Tashar. He'll know what to do with it. If it works, we can use it to reinforce the shield generators at the larger domes.", sourceObjective = "Bring the Repair Apparatus to Tashar at Eco-Dome Farfield in Netherstorm.", progress = "It looks like you've got the prototype. Did Ghabar send you?", completion = "This looks a little peculiar. Ghabar definitely didn't have Netherstorm in mind when he designed it.\n\nDon't look so surprised, {name}. Netherstorm is tame compared to some of the environments I've worked in. Nevertheless, a failing dome is always a concern.", sourceObjectiveStatus = "unverified-source-field" }
quests[10431] = { id = 10431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Outside Assistance", description = "The Sunfury briefings support the theory that Kael'thas has been receiving outside help in constructing and running these manaforges.  Who this is remains a bit of a mystery, though we're likely to find out in Manaforge Ara.\n\nI've sent a group of my men to scout the surrounding area.  Go to Tuluman's Landing, north of here, and speak to Kaylaan.  See what he's discovered at Manaforge Ara.  Find out who is assisting the Sunfury army and take care of them.", sourceObjective = "Go to Tuluman's Landing, north of Area 52, and speak to Kaylaan.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", completion = "You're all the help Orelis is sending?  He must think very highly of you.\n\nLet's get this over with.", sourceObjectiveStatus = "unverified-source-field" }
quests[10432] = { id = 10432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Damning Evidence", description = "As you may have noticed, there are servants of the Burning Legion all over Manaforge Ara.  Kael'thas has entered an alliance with the Burning Legion.  He must've caught wind of Illidan's descent into insanity and switched paymasters accordingly.\n\nIf the Scryers get definite proof of this, it will give them a considerable political advantage.  I know for a fact that the Legion forces at this manaforge have orders that bear Kael's seal.\n\nGet these orders and bring them to Thalodien.", sourceObjective = "Obtain 8 Orders from Kael'thas from demons at Manaforge Ara and bring them to Spymaster Thalodien in Area 52.\n\nPerforming quests for the Scryers will cause your Aldor reputation to decrease.", progress = "Well?  What did Theledorn have to say?", completion = "This is big, {name}.  Very big!\n\nVoren'thal is going to want to hear about this as soon as possible.", sourceObjectiveStatus = "unverified-source-field" }
quests[10433] = { id = 10433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping Up Appearances", description = "The ethereals are clever and very observant, so it's no accident that I'm here posing as a simple furrier. In fact, I've been sent from Area 52 to appraise the technology the ethereals use to generate their eco-domes.\n\nI'd like to enlist your help, {class}. We've been asked to use non-goblin agents whenever possible.\n\nWhat I want you to do is bring me a number of ripfang lynx pelts in the guise of a hunter. You can find the lynxes all over Eco-Dome Midrealm.", sourceObjective = "Bring 10 Ripfang Lynx Pelts to Shauly Pore at Midrealm Post.", progress = "<Shauly raises his voice so as to catch the attention of the ethereals in the area.>\n\nHave any pelts to sell me?", completion = "<Shauly makes a show of admiring the skins.>\n\nThese are magnificent, utterly magnificent! I'll pay you top coin for these! How much to retain your services?", sourceObjectiveStatus = "unverified-source-field" }
quests[10434] = { id = 10434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dynamic Duo", description = "Excellent job.\n\n<Shauly winks at you.>\n\nI think they're buying it. Now, when I send you up to speak with my associates at the Stormspire, there won't be any suspicion at all.\n\nYou'll want to look for Action Jaxon and Audi the Needle up there. They'll tell you everything you need to know. Tell 'em Shauly sent you.", sourceObjective = "Speak with Audi the Needle at the Stormspire in Netherstorm.", completion = "<You introduce yourself and tell Audi that Shauly sent you.>\n\nAh, yes, we've been expecting someone to help us, err -- move some, uh, merchandise.", sourceObjectiveStatus = "unverified-source-field" }
quests[10435] = { id = 10435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retrieving the Goods", description = "<Audi looks around and then lowers her voice.>\n\nI'm sure Shauly told you a bit about our work here. When Jaxon and I are out in the field 'hunting,' we've been collecting pieces of the ethereal eco-dome generators and hiding them in the nests of our prey, the raptors in Eco-Dome Farfield.\n\nIt's a remote area to the northeast of the Stormspire, close to the Netherstone. I don't anticipate you'll run into many ethereals there, but would you be willing to help us collect the dome generator pieces?", sourceObjective = "Audi the Needle at the Stormspire wants you to bring her 10 Dome Generator Segments.", progress = "Did you collect everything?", completion = "Excellent work! The most difficult part of the project is done. Now, all we need is a way to get these back to Area 52 and attract the interest of the Cenarion Expedition as well. There should be enough here for our own needs and to earn a little profit on the side.", sourceObjectiveStatus = "unverified-source-field" }
quests[10436] = { id = 10436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Clear!", description = "Before we can begin the test, we have to make certain the area is clear of anything that might interfere. In our case, that means these overgrown lizards.\n\n<Tashar gestures toward the scythetooth raptors.>\n\nThere's no telling what might happen if one of those decides to take a nice bite out of the generator while it's charging. I've seen a lot of strange things in all my years as a technician, including more than a few abominations that had their beginnings as humble animals.", sourceObjective = "Tashar, stationed at Eco-Dome Farfield, wants you to kill 12 Scythetooth Raptors.", progress = "Have you cleared the test area?", completion = "Well done. It looks like everything is in order. We're ready to begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[10437] = { id = 10437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recipe for Destruction", description = "Atop Manaforge Ultris lies the tear in the nether that the void lord, Dimensius, came through. That tear provides Dimensius with a link to the void, rendering him immune to physical harm. If we can get a lock on the conduit that Dimensius is using to keep himself phased out of this plane of existence, we can destroy it and then destroy Dimensius.\n\nTo do this, we're going to first need you to collect fragments of Dimensius from the void creatures that he sends out to do his dirty work.", sourceObjective = "Professor Dabiri at the Protectorate Watch Post in Netherstorm wants you to recover 8 Fragments of Dimensius.", progress = "Have you collected enough fragments?", completion = "Excellent. With these fragments, we can calibrate a bomb that will destroy the void conduit atop Ultris. With the void conduit destroyed, Dimensius's connection with the void will be severed and he will be left defenseless!", sourceObjectiveStatus = "unverified-source-field" }
quests[10438] = { id = 10438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Nethery Wings", description = "Here it is, {name}. Take this phase disruptor and mount up! The Protectorate nether drake will fly you close enough to Ultris so that you can drop the disruptor on top of the void conduit.\n\nDrop as many disruptor charges as possible to ensure complete annihilation!\n\nWhen you are ready, speak with the nether drake and he'll take you up.\n\nIf you miss the mark you will have to get more bombs from me before you can go up again.", sourceObjective = "Professor Dabiri at the Protectorate Watch Post in Netherstorm wants you to use your Phase Disruptor when you get in range of the Void Conduit that rests atop Ultris. Drop as many charges of the Phase Disruptor as you can to ensure total annihilation. The Phase Disruptor charges will automatically home in on the Void Conduit so long as you are close enough to use it.\n\nReturn to Professor Dabiri should you succeed!", progress = "Did you hit the mark?", completion = "The time to strike has come! With the tear gone, Dimensius is vulnerable to physical and magical attacks!", sourceObjectiveStatus = "unverified-source-field" }
quests[10439] = { id = 10439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dimensius the All-Devouring", description = "Your brave actions have forced Ameer to react! He has deployed Captain Saeed and the Avengers!\n\nNow all that is left to do is destroy Dimensius.\n\nWhen you are ready, I will call for Saeed. If he is not currently fighting another battle, he will be awaiting orders from you - directly east of here.\n\nLet him know when you are ready to fight and he will put his troops in motion!\n\nI wish you luck, fleshling! We have hunted Dimensius for a thousand years!", sourceObjective = "Professor Dabiri at the Protectorate Watch Post in Netherstorm wants you to speak with Captain Saeed and then follow his army to Manaforge Ultris and kill Dimensius the All-Devouring!", progress = "What of the void lord?", completion = "For a thousand years, all we have known is conflict. We have defended our people from the attacks of both void creature and ethereal alike.\n\nNow, one of our most hated enemies lies dead - finally.\n\nI give you the thanks of a hundred million ethereals, fleshling.", sourceObjectiveStatus = "unverified-source-field" }
quests[10440] = { id = 10440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Success!", description = "The test was a resounding success! We can certainly use this device to start repairing the domes.\n\nCarry word of the test results to the Stormspire and let Ghabar know that I've also found a pattern in the damage to the shield generators. Key pieces of generator units have gone missing from a number of sites. This is no accident, {name}, no technological failure. We're being stolen from.", sourceObjective = "Return to Ghabar at the Stormspire in Netherstorm.", completion = "I'll have my techs get to work on those repairs right away.\n\nTashar's suspicion of sabotage worries me, though. I can't think of anyone who would be bold enough to steal our technology. Not anyone who knows what we're capable of, anyway. It may be time to lock down the Stormspire.", sourceObjectiveStatus = "unverified-source-field" }
quests[10441] = { id = 10441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peddling the Goods", description = "<Audi lowers her voice again.>\n\nNow that we have the goods, I'll be sending most of the parts on to Area 52. There's enough here for more than one generator, presenting us with a perfect business opportunity.\n\nI've seen the Cenarion Expdedition's representative trying to negotiate. I want you to let her know that we can provide what she seeks at a very reasonable price. There's no reason for her to continue dealing with those two-timing ethereals.", sourceObjective = "Speak with Aurine Moonblaze at the bottom of the Stormspire in Netherstorm.", sourceObjectiveStatus = "unverified-source-field" }
quests[10442] = { id = 10442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helping the Cenarion Post", description = "{class}, there's some tauren by the name of Thiah Redmane that keeps pestering us for assistance.  She's with the Cenarion Expedition, and they've setup a little post just to the west on the south side of the road leading to Zangarmarsh.\n\nIf you hit Thornfang Hill, you've gone too far.\n\nDo you think you might head over there and see what she needs?  I don't want to have to bother Ranger Captain Venn'ren with such trivialities.", sourceObjective = "Falconer Drenna Riverwind wants you to offer your services to Thiah Redmane at the Cenarion Post in Hellfire Peninsula.", completion = "Oh, goodness, you must be the help I requested weeks ago from Falcon Watch.\n\nWell, you're here now and there's a lot to be done.  I have just the thing to start you out.", sourceObjectiveStatus = "unverified-source-field" }
quests[10443] = { id = 10443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helping the Cenarion Post", description = "The Cenarion Circle has sent an expedition to Outland and, as I understand it, they are here to study what has happened and to help reverse any damage that they can.\n\nThey've setup a little post just to the west on the south side of the road leading to Zangarmarsh.\n\nIf you hit Thornfang Hill, you've gone too far.\n\nWould you please go and see how you might help them?  Speak with Thiah Redmane as she is the one that sent the request to us for assistance.", sourceObjective = "Amaan the Wise would like for you to offer your services to Thiah Redmane at the Cenarion Post in Hellfire Peninsula.", completion = "Oh, goodness, you must be the help that I requested from the Temple of Telhamat.\n\nI'm glad that you're here; there's a lot to be done, and I have just the thing to start you out.", sourceObjectiveStatus = "unverified-source-field" }
quests[10444] = { id = 10444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to the Allerian Post", description = "This calls for immediate action!\n\nWe have someone out in the field closer to Firewing Point that I want you to speak with.  He'll have a better idea of what our next step should be.\n\nReport to Lieutenant Meridian out at the Allerian Post and apprise him of the situation.  You'll find the post to the northeast on the southern bank of the river just south of Firewing Point.\n\nGodspeed, {name}.", sourceObjective = "Jenai Starwhisper wants you to report to Lieutenant Meridian at the Allerian Post in Terokkar Forest.", completion = "Bomb parts.  So my suspicions were true.  That's not something that I wanted to be right about.\n\nOkay, you and I have some grim business ahead of us then.", sourceObjectiveStatus = "unverified-source-field" }
quests[10445] = { id = 10445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vials of Eternity", description = "Seven vials were drawn from the Well of Eternity by Illidan.  He poured three into the lake on top of Mount Hyjal and a second Well of Eternity was created.  For years the rest were believed lost.\n\nWith the opening of the Dark Portal, we've come to know that he gave one each to his lieutenants Kael'thas and Vashj.  Retrieve what remains of them; we will need them as foci to open a gateway to any events tied to Mount Hyjal, recent or ancient.  The outcome of the Battle of Mount Hyjal must be preserved.", sourceObjective = "Soridormi at Caverns of Time wants you to retrieve Vashj's Vial Remnant from Lady Vashj at Coilfang Reservoir and Kael's Vial Remnant from Kael'thas Sunstrider at Tempest Keep.", progress = "I've asked the impossible of you, yet I expect you to succeed.  Much depends on it.", completion = "The power contained even in this small amount of water from the Well of Eternity is incredible.\n\nI can see clearly into every moment in time linked to Hyjal... the creation of the second Well of Eternity, Illidan's imprisonment, the enchantment of the World Tree and... yes!  The Battle of Mount Hyjal.\n\nWe must make haste, the timeline is not safe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10446] = { id = 10446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Code", description = "They're building a second mana bomb in the courtyard.  My intel suggests that the final code for the bomb is being held by Sharth Voldoun, the overseer of the project at Firewing Point.\n\n{name}, you have to go back in there and retrieve the final code from him.  He keeps himself to the top of the highest spire.\n\nTake the final code to the mana bomb that they're working on in the central courtyard and set it off.\n\nOnly then will we be certain that the Allerian Stronghold is safe.", sourceObjective = "Lieutenant Meridian wants you to use The Final Code to set off the Mana Bomb. Then report back to Jenai Starwhisper at the Allerian Stronghold in Terokkar Forest.", completion = "YOU DID IT!  YOU SAVED US!  YOU SAVED THE ALLERIAN STRONGHOLD!!\n\nWith their forces decimated, their leader dead and the mana bomb destroyed, we can all breathe much easier now.\n\n{name}, I've never seen such selflessness... such heroism!  Please, accept this on behalf of all of us.", sourceObjectiveStatus = "unverified-source-field" }
quests[10447] = { id = 10447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Code", description = "They're building a second mana bomb in the courtyard.  My intel suggests that the final code for the bomb is being held by Sharth Voldoun, the overseer of the project at Firewing Point.\n\n{name}, you have to go back in there and retrieve the final code from him.  He keeps himself to the top of the highest spire.\n\nTake the final code to the mana bomb that they're working on in the central courtyard and set it off.\n\nOnly then will we be certain that Stonebreaker Hold is safe.", sourceObjective = "Sergeant Chawni wants you to use the Final Code Sheet to set off the Mana Bomb. Then report back to Tooki at Stonebreaker Hold in Terokkar Forest.", completion = "YOU DID IT!  YOU SAVED US!  YOU SAVED STONEBREAKER HOLD!!\n\nWith their forces decimated, their leader dead and the mana bomb destroyed, we can all breathe much easier now.\n\n{name}, I've never seen such selflessness... such heroism!  Please, accept this on behalf of all of us.", sourceObjectiveStatus = "unverified-source-field" }
quests[10448] = { id = 10448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Stonebreaker Camp", description = "This calls for immediate action!\n\nWe have someone out in the field closer to Firewing Point that I want you to speak with.  She'll have a better idea of what our next step should be.\n\nReport to Sergeant Chawni out at Stonebreaker Camp and apprise her of the situation.\n\nTake the road north out of the hold.  From the middle of Tuurem, follow the road to the east.  You'll find the camp on the bank of the river that lies just southwest of Firewing Point.\n\nGood luck, {name}.", sourceObjective = "Tooki wants you to report to Sergeant Chawni at Stonebreaker Camp in Terokkar Forest.", completion = "Bomb parts. So my suspicions were true.  That's not something that I wanted to be right about.\n\nOk, you and I have some grim business ahead of us then.", sourceObjectiveStatus = "unverified-source-field" }
quests[10449] = { id = 10449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apothecary Zelana", description = "Apethecary Zelana has been studying the beasts of Hellfire Peninsula in the field.  She wants a sample of the blood you gathered; with luck, she might discover what turned those Bonechewer freaks' skins red!\n\nZelana is at Reaver's Fall, southeast of Thrallmar.  Follow the road east and when you see a destroyed, green-glowing hunk of metal, you're there.  She has a camp set up behind the wyverns.", sourceObjective = "Vertok Axebreaker in Thrallmar wants you to bring Bonechewer Blood Samples to Apothecary Zelana at Reaver's Fall.", progress = "It is my honor to serve the wishes of the Horde.  How might I aid you?", completion = "Ah, yes.  The blood of the Bonechewer clan.  I am very curious about these orcs... they are still the depraved fiends of the past, but their strength and power is greater than what I had heard...\n\nWell, let us begin, shall we?", sourceObjectiveStatus = "unverified-source-field" }
quests[10450] = { id = 10450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonechewer Blood", description = "Bonechewers!  They should all die!  The sight of their red skin and depravity makes my blood boil!\n\nI have a mission for you, {name}.  Kill Bonechewer orcs and collect their vile blood.  There is an apothecary who needs the blood for her tests, so we can discover how these orcs fell to the demon taint, a taint from which we so recently freed ourselves.\n\nBonechewers scavenge near the ruined battlements along the Path of Glory, to the south.  Return to me when your mission is complete.", sourceObjective = "Bring 12 Bonechewer Blood Vials to Vurtok Axebreaker in Thrallmar.", progress = "Did you face the bonechewers, {name}.  I hope their blood was spilled in great gouts!", completion = "Hah!  So you did meet the bonechewers, our depraved cousins.  Well done, {name}.  My only regret is that more of them could not lay down their lives and spill their blood, to cool my outrage!", sourceObjectiveStatus = "unverified-source-field" }
quests[10451] = { id = 10451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Coilskar Cistern", description = "Thank the Earthmother! I parted ways with the others several days ago. I was intent on discovering the source of the disturbance that the spirits of water were feeling. My search led me to Coilskar where I discovered that the naga were befouling the water supply of Shadowmoon Valley.\n\nUnfortunately, I was discovered and taken prisoner. There's no telling what ghastly things they had in store for me.\n\nWe must leave this place! Help me escape and then seek out Torlok at the Altar of Damnation.", sourceObjective = "Escort Earthmender Wilda out of Coilskar Cistern and then seek out Earthmender Torlok at the Altar of Damnation, found at the western outskirts of the Hand of Gul'dan.", completion = "Praise the Earthmother. I am certain that Wilda will find her way home. Please accept this as a token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10455] = { id = 10455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Encroaching Wilderness", description = "We've been growing the Living Grove at an accelerated rate, but somehow the lynxes there have become lost to our control.\n\nWhere once their population was stable, the grovestalker lynxes are now beginning to encroach upon Sylvanaar, and there have been a number of unpleasant incidents of late.\n\nI suspect that the arakkoa of Veil Lashh are somehow behind it, but the immediate issue is with the lynxes themselves.\n\nI would be most grateful if you would help us to deal with this situation.", sourceObjective = "Slay 12 Grovestalker Lynxes.", completion = "That was fast.  Are you sure that you dealt with as many as was necessary?\n\nExcellent, there's something else that you can help us with if you are willing?", sourceObjectiveStatus = "unverified-source-field" }
quests[10456] = { id = 10456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marauding Wolves", description = "The filthy races of the Horde have taken over a settlement to the east.  They've brought with them a large pack of the dire wolves that they prefer to use as mounts and sentries.\n\nThese sentries have been marauding across the bridge that separates us.  They've been stalking our fey drakes, which are critical to the pollination of the Living Grove.\n\nUse the east exit to traverse the bridge over Bloodmaul Ravine that leads to the Jagged Ridge to the east, and bring me their tails as proof!", sourceObjective = "Collect 4 Thunderlord Dire Wolf Tails.", progress = "I cannot stress strongly enough the need for those Thunderlord dire wolves to be dealt with.  Their very existence endangers the stability of the Living Grove and all of our work here.", completion = "Good.  I'll see if I can fashion something useful from these tails.\n\nNo doubt that the Horde will find a way to replenish the numbers of their wolf pack, but for now we can breathe a little easier.\n\n{name}, if you are willing there's something else that I would ask of you in defense of Sylvanaar and the Living Grove.", sourceObjectiveStatus = "unverified-source-field" }
quests[10457] = { id = 10457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protecting Our Own", description = "Though you've done a great deal of good work in defense of our new home here, I still feel that the Living Grove needs more protection.\n\nPlease, take this small tree bough that I have imbued with the force of nature.  When used upon the seedlings that I have planted out in the grove, it will call down a storm to accelerate the growth of a treant defender.\n\nThese treants are critical to the defense of the grove, especially if you choose not to make Sylvanaar your home for long.", sourceObjective = "Use Rina's Bough on 5 of the Grove Seedlings to summon forth defenses for the Living Grove.", progress = "How fares the bolstering of the Living Grove's defenses?\n\nWith the intentions of the arakkoa at Veil Lashh unknown, and the Horde just on the other side of the ravine, I fear that if we do not move quickly we will find ourselves in a poor situation to protect our new home and our work in the grove.", completion = "Now that you have strengthened the grove's defenses, I feel much safer.\n\nYou've earned our thanks and appreciation, {name}.\n\nOf course, it just occurred to me that there's something else that we need to take care of!", sourceObjectiveStatus = "unverified-source-field" }
quests[10458] = { id = 10458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enraged Spirits of Fire and Earth", description = "We must try and make amends. We must commune with the elements of this region and see if anything can be done!\n\nI grant you the totem of spirits, {race}. If you slay an enraged elemental spirit in close proximity of the totem, it will consume the elemental's soul. You must use the totem to consume many souls before you may return to me.\n\nDo this for the spirits of fire and earth first. Return to me when the totem is full.", sourceObjective = "Earthmender Torlok at the Altar of Damnation in Shadowmoon Valley wants you to use the Totem of Spirits to capture 8 Earthen Souls and 8 Fiery Souls.", progress = "I fear that this land may be without hope.", completion = "When all of the elemental souls of this region have been placed inside the totem, we will commune with them and find out if anything can be done for Shadowmoon Valley.", sourceObjectiveStatus = "unverified-source-field" }
quests[10459] = { id = 10459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revered Among the Cenarion Expedition", description = "We've taken notice of your accomplishments, {name}.  What you've done for us goes beyond what we expect from our allies.\n\nI've a special request to ask of you, but I must test your dedication first.", sourceObjective = "Ysiel Windsinger at the Cenarion Refuge wants you to become revered with the Cenarion Expedition.", sourceObjectiveStatus = "unverified-source-field" }
quests[10460] = { id = 10460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defender's Pledge", sourceObjective = "Are you sure this is the path you seek to take, {name}?  This is not a decision you ought to take lightly.\n\nThis ring is imbued with a droplet from the Well of Eternity.  It will grow in power as you prove yourself to the Scale of the Sands.", sourceObjectiveStatus = "unverified-source-field" }
quests[10461] = { id = 10461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restorer's Pledge", sourceObjective = "Are you sure this is the path you seek to take, {name}?  This is not a decision you ought to take lightly.\n\nThis ring is imbued with a droplet from the Well of Eternity.  It will grow in power as you prove yourself to the Scale of the Sands.", sourceObjectiveStatus = "unverified-source-field" }
