quests[10463] = { id = 10463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sage's Pledge", sourceObjective = "Are you sure this is the path you seek to take, {name}?  This is not a decision you ought to take lightly.\n\nThis ring is imbued with a droplet from the Well of Eternity.  It will grow in power as you prove yourself to the Scale of the Sands.", sourceObjectiveStatus = "unverified-source-field" }
quests[10464] = { id = 10464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sage's Vow", description = "You've made your pledge, {class}.  Now it is up to you to see it through.\n\nServe the Scale of the Sands well and you will be rewarded.\n\nFail and the timeline as we know it will be unravelled!", sourceObjective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Honored reputation with the Scale of the Sands.", progress = "You continue to serve us well, {name}.", completion = "You've proved your worth, {race}.  Up to a certain point, at least.\n\nThe favor of Nozdormu's prime mate is not obtained easily.", sourceObjectiveStatus = "unverified-source-field" }
quests[10465] = { id = 10465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restorer's Vow", description = "You've made your pledge, {class}.  Now it is up to you to see it through.\n\nServe the Scale of the Sands well and you will be rewarded.  Fail and the timeline as we know it will be unravelled!", sourceObjective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Honored reputation with the Scale of the Sands.", progress = "You continue to serve us well, {name}.", completion = "You've proved your worth, {race}.  Up to a certain point, at least.\n\nThe favor of Nozdormu's prime mate is not obtained easily.", sourceObjectiveStatus = "unverified-source-field" }
