quests[10468] = { id = 10468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sage's Oath", description = "You've carried out the promise you made to us, {name}.  And for that you've gained the recognition you deserve.\n\nAs you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring.  It won't be long until it has reached its full potential.", sourceObjective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Revered reputation with the Scale of the Sands.", progress = "You've returned.  You wish to speak to me?", completion = "You are a worthy ally indeed.  As you grow in power so does the band of eternity!", sourceObjectiveStatus = "unverified-source-field" }
quests[10469] = { id = 10469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restorer's Oath", description = "You've carried out the promise you made to us, {name}.  And for that you've gained the recognition you deserve.\n\nAs you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring.  It won't be long until it has reached its full potential.", sourceObjective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Revered reputation with the Scale of the Sands.", progress = "You've returned.  You wish to speak to me?", completion = "You are a worthy ally indeed.  As you grow in power so does the band of eternity!", sourceObjectiveStatus = "unverified-source-field" }
