quests[10475] = { id = 10475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defender's Covenant", description = "Your accomplishments have gone beyond my greatest expectations, {name}.\n\nYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.\n\nContinue to serve the Scale of the Sands and I will unleash your gift's full potential.", sourceObjective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Exalted reputation with the Scale of the Sands.", progress = "May time always be on your side, {name}.", completion = "You are one with time, {name}.  You are one with us.\n\nBehold!  Power beyond mortal understanding is unleashed from even that small remnant of the Well of Eternity.\n\nAccept this gift so that all may know of your covenant with the Scale of the Sands.... so that all may know of your covenant with time itself!", sourceObjectiveStatus = "unverified-source-field" }
quests[10476] = { id = 10476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fierce Enemies", description = "If you seek to prove your loyalty to us, there is no better way than to fight against our enemies.\n\nOf these, there are none that can match the ogres in strength and fierceness.  Bring me the warbeads they wear around their necks as proof of their demise and I'll let the others know of your prowess.", sourceObjective = "Warden Moi'bff Jill at Telaar wants you to obtain 10 Obsidian Warbeads from the various ogres that inhabit Nagrand.", progress = "Well, {name}?  Are you all talk or do you have something to show me?", completion = "You're starting to prove your worth as an ally and combatant.  Keep up the good work.", sourceObjectiveStatus = "unverified-source-field" }
quests[10477] = { id = 10477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Warbeads", progress = "Do you bear any additional obsidian warbeads, {name}?", completion = "You continue to prove your worth to us, {name}.  May your strength never fail you." }
quests[10478] = { id = 10478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Warbeads!", progress = "Have you obtained more warbeads, {name}?", completion = "You continue to prove your strength and honor, {name}." }
quests[10479] = { id = 10479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Your Strength", description = "Though we seek a peaceful life, our enemies are many.  Of these, none match the ogres in sheer brute power.\n\nIf you seek to prove your prowess to us, bring me the warbeads they wear around their necks.  I will tell others of your accomplishments.", sourceObjective = "Warden Bullrok at Garadar wants you to obtain 10 Obsidian Warbeads from the various ogres that inhabit Nagrand.", progress = "You have something to show me, {name}?", completion = "You are a strong ally indeed, {name}.  Going head to head against the ogres of Outland is not something that just anyone can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10480] = { id = 10480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enraged Spirits of Water", description = "The Illidari naga of the region have taken control of the only clean water supply that exists in Shadowmoon Valley.\n\nDirectly north of here you will find the lair of the naga: Coilskar. Around Coilskar are pockets of agitated water that howl to the land in anguish. It is at those pockets that the enraged spirits of water now wander.\n\nTravel to Coilskar and use the totem of spirits to capture watery souls. You will find the largest concentration of these spirits near Coilskar Cistern.", sourceObjective = "Earthmender Torlok at the Altar of Damnation in Shadowmoon Valley wants you to use the Totem of Spirits to capture 5 Watery Souls.", progress = "Wherever you find naga you will almost certainly find tortured water spirits.", completion = "Only air remains, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10481] = { id = 10481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enraged Spirits of Air", description = "Venture southeast, hero. When you see fields of gigantic blue crystals jutting out from the land, you will have reached your destination. It is there, at the Netherwing Fields, that you will find the enraged spirits of air. They roam the cliffs and mountain bases that surround the fields.\n\nDestroy their tortured forms and capture their souls with the totem of spirits. Return to me when this is done.", sourceObjective = "Earthmender Torlok at the Altar of Damnation in Shadowmoon Valley wants you to use the Totem of Spirits to capture 10 Airy Souls.", progress = "Soon, we will speak with the spirits.", completion = "Allow me to reward you for undertaking such an arduous task, hero.\n\nNow, we must get to work! Please stand back so that I may place the totem and unleash the souls.", sourceObjectiveStatus = "unverified-source-field" }
quests[10482] = { id = 10482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Orc Scavengers", description = "Scavengers, orcs of the Bonechewer clan, skulk about the ruined battlements overlooking the Path of Glory. We must assume that these fel orcs are gathering war machine parts for their masters within Hellfire Citadel--they must be stopped!\n\nFind Bonechewer orcs to the north, {name}. Find them and slay them! But use caution, for although these orcs are the lesser of the fel clans, their strength is the match of any orc we've faced thus far.", sourceObjective = "Kill 20 Bonechewer Orcs and return to Amadi in Honor Hold.", progress = "The Bonechewers appear in large numbers, {name}.  Slay them or the fel orcs may overrun us!", completion = "Very good.  I'm sure their loss will be felt in Hellfire Citadel.  Although that dark bastion looms over us and seems nigh insurmountable, it is only with bold moves like you have made that we will find victory over the fel orcs!", sourceObjectiveStatus = "unverified-source-field" }
quests[10483] = { id = 10483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ill Omens", description = "{name}, in our battles with the Bleeding Hollow clan of fel orcs, we have found upon them foreboding trinkets.  These orcs have collected the insignias of fallen Honor Hold soldiers and created cursed talismans from them.  We fear the dark magic of the Bleeding Hollow orcs have transformed our insignias into evil charms with powers against us!\n\nFind such a talisman from the Bleeding Hollow orcs of Zeth'Gor, to the east, and bring it to Corporal Ironridge at Expedition Point, northeast of Zeth'Gor.", sourceObjective = "Lieutenant Amadi in Honor Hold wants you to bring 1 Cursed Talisman to Corporal Ironridge at Expedition Point.", progress = "Reporting from Honor Hold, {name}?  That's good -- our campaign against the demons and the fel orcs is running thin on able bodies!", completion = "Ah, you recovered an insignia from the Bleeding Hollow orcs?  Good -- it is outrageous that they use our own symbols against us, and mock our comrades who've fallen to those red-skinned beasts!", sourceObjectiveStatus = "unverified-source-field" }
quests[10484] = { id = 10484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cursed Talismans", description = "{name}, we cannot allow the Bleeding Hollow orcs to possess their cursed talismans!  You must acquire them for us so they may be disposed of, and so the soldiers who owned them may be honored for their sacrifices.\n\nGo to Zeth'Gor, the cursed abode of the Bleeding Hollow, and perform your grim task... return to me when you have collected the talismans.", sourceObjective = "Bring 12 Cursed Talismans to Corporal Ironridge at Expedition Point.", progress = "Do you have the talismans, {name}?  It pains me to know that those cursed orcs possess our soldiers insignias...", completion = "Thank you, {name}.  My heart is saddened to see these talismans -- they underline the great losses we of Honor Hold have suffered against the fel orcs.  But I am heartened to see you successful against them.  If we can kill enough, perhaps we might emerge from this war victorious.", sourceObjectiveStatus = "unverified-source-field" }
quests[10485] = { id = 10485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlord of the Bleeding Hollow", description = "You have shown great strength and fortune, for you have delved into Zeth'Gor and lived!  Now, let us hope your fortune holds, for I have a dire task to ask of you...\n\nWarlord Morkh sits within the barracks of Zeth'Gor, commanding his fel troops against us.  His tactics are as clever as they are cruel, and I must admit that his successes against us have cut deep.  And so, {name}, I ask you to remove Morkh from his seat.  Bring me his armor so that we might display it for our soldiers and bolster them.", sourceObjective = "Bring Warlord Morkh's Shattered Armor to Corporal Ironridge in Expedition Point.", progress = "Do you have Morkh's shattered armor?  Have you braved Zeth'Gor again?", completion = "You've done it!  Morkh is slain!  Now, we have a fighting chance against the fel orc beasts!\n\nThank you, {name}.  Your aid to the war effort here is beyond measure.", sourceObjectiveStatus = "unverified-source-field" }
quests[10486] = { id = 10486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Encroaching Wilderness", description = "The Thunderlord were once a proud orc clan before they were transformed into fel orcs through the blood of Mannoroth.\n\nRecently we recovered this orc stronghold from the ogres that infest the ravine below.  They had moved in when the Thunderlord clan abandoned it.\n\nWe will keep this place and I will have your help doing so.\n\nIn the Jagged Ridge to the south and the west, there are bloodletters that have become like a plague upon us.  They eat and breed incessantly.\n\nKill them and then return to me.", sourceObjective = "Slay 12 Bladewing Bloodletters.", progress = "Our survival here depends upon our ability to concentrate our efforts against those that truly matter, not the mere bladewing bloodletters.\n\nYou are here again, so this must mean that you have dealt with the matter at hand?", completion = "That didn't take as long as I thought it would.  Are you sure that you dealt with as many as was necessary?\n\nVery well, there's something else that I want you to help us with.  Something far more important.", sourceObjectiveStatus = "unverified-source-field" }
quests[10487] = { id = 10487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dust from the Drakes", description = "The Alliance has recently moved in to the west, using their elven magics to grow a town and grove in a short matter of time.  We must keep their defenses weak so that they do not also grow a spine.\n\nI have a plan that will do that and more.  I want you to traverse the bridge to the southwest, which crosses over Bloodmaul Ravine and leads into the Living Grove.\n\nAttack their fey drake defenses in the Living Grove and bring back the magical dust that sometimes can be found upon their wings.", sourceObjective = "Collect 4 Dusts of the Fey Drake.", progress = "It would seem that the Alliance is determined to follow us wherever we go.  Let us teach them that we are not intimidated by their presence.\n\nDo you have that which I have requested?", completion = "Not only have you weakened their defenses, but we're going to put this dust to use in bolstering our own defenses against the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[10488] = { id = 10488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protecting Our Own", description = "With the magical dust you recovered, I have fashioned a magic ointment that will aid in our own defenses.\n\nOur dire wolves are the perfect combination of mount, sentry and friend, but the Alliance scum have been poaching them in the Jagged Ridge.\n\n{name}, I want you to take this ointment and apply it to our dire wolf friends.  The Alliance will get a rude surprise the next time that they send one of their hunting parties.\n\nBe aware though that some of the wolves may not like this, and will turn on you.", sourceObjective = "Use Gor'drek's Ointment on 5 of the Thunderlord Dire Wolves.", progress = "How fares the bolstering of our Thunderlord dire wolves' defenses?", completion = "Now that you have strengthened the wolves, and the Jagged Ridge's defenses, perhaps we can refocus our attentions on more deadly matters, such as the ogres?\n\nYou have done a good job in aiding us here.  We could use the help of someone capable, such as yourself, should you decide to stay.\n\nWhatever you do, you have earned my respect and appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10489] = { id = 10489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felling an Ancient Tree", description = "WANTED!\n\nStronglimb Deeproot, ancient of war and chief defender of the Living Grove south of Sylvanaar.\n\nFind him by heading west across the bridge that traverses the Bloodmaul Ravine.\n\nReturn his hewn trunk to Tor'chunk Twoclaws.", sourceObjective = "Collect Stronglimb Deeproot's Trunk.", progress = "What's that you have there?  You're a strong one!", completion = "Stronglimb Deeproot's Trunk!  Did you chop him down by yourself?\n\nI bet you did.  You know, Rexxar and I are looking for a young, strong {class}, such as yourself, to help out around here, especially with the problems we continually have with the ogres.  Make sure that you follow-up with me on that possibility.\n\nWell that trunk's definitely proof, which means you're here to collect the bounty and not to listen to me talk.  Go ahead, take your pick.", sourceObjectiveStatus = "unverified-source-field" }
quests[10490] = { id = 10490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "I'm sensing that it's been a while since last you were tested.  This is because Farseer Nobundo has been asking for you.\n\nYou must have grown greatly in wisdom because you are being called to learn the mysteries of the element of water.\n\nI trust that you remember how to take the boat from Auberdine in Darkshore on Kalimdor back to the Exodar?  And that you remember where to find the farseer at the Crystal Hall inside the Exodar, yes?", sourceObjective = "Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle.", completion = "We meet again.  I have been watching your progress from afar, {class}, and I am pleased.\n\nThe time has come for you to commune with the element of water, to learn its mysteries and give yourself over to the water so that you might in turn learn to master it.", sourceObjectiveStatus = "unverified-source-field" }
quests[10491] = { id = 10491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air", description = "{name}, once again Farseer Nobundo has been asking for you.  It must be time for you to learn the secrets of air, the last of the elements!\n\nI want you to know that I'm very proud of all that you have accomplished thus far.  I know that you have great things ahead of you.\n\nTake the boat from Auberdine in Darkshore on Kalimdor.  Cross the Veiled Sea and seek out the farseer inside the Crystal Hall of the Exodar on Azuremyst Isle.", sourceObjective = "Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle.", completion = "And finally we come to it, the last of the four great elements: air.  Do you think yourself wise enough to continue, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[10492] = { id = 10492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Earnest Proposition", description = "Well met, {class}.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.", sourceObjective = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Bindings of Elements to Deliana in Ironforge.", progress = "Have you brought me what I requested of you, {name}?", completion = "Excellent!  Let's perform the trade then.  It's hard to part with this excellent armor, but I'm afraid I won't be needing it any time soon.\n\nIf you're interested in performing more work for me, I might be willing to give up the rest of the pieces.", sourceObjectiveStatus = "unverified-source-field" }
quests[10493] = { id = 10493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Earnest Proposition", description = "Hail, {class}!  I can tell by your demeanor that you've seen and done much in this world.  Yet I'm willing to wager you haven't seen a piece of armor like this.\n\nPerform a small favor for me and I'll be willing to trade it to you for an ordinary set of bracers.\n\nI'm in need of a sizeable sample of venom drawn from the spiders and scorpions that inhabit Silithus.  Bring this to me along with a few gold coins and I'll perform the exchange.", sourceObjective = "Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Lightforge Bracers to Mokvar in Orgrimmar.", progress = "Have you obtained the items I require, {name}?", completion = "Ah, yes.  Mux will be quite happy with this.\n\nThose bracers were part of a larger armor set.  If you're interested in providing me with further assistance,  I'd be willing to consider parting with the rest of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[10494] = { id = 10494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Compensation", description = "You kept your word and brought the device built by Mux.  I believe a reward is in order if I'm to keep you interested in saving my skin.  Bring me the belt and set of gloves that you wish to upgrade.  I promise the ones I give you in return will be far superior.", sourceObjective = "Bring a Cord of Elements and a set of Gauntlets of Elements to Deliana in Ironforge.", progress = "You're ready to perform the trade?", completion = "You've kept your end of the bargain, I shall keep mine.\n\nJust remember that I'm holding on to the best pieces until your work is finished.", sourceObjectiveStatus = "unverified-source-field" }
quests[10495] = { id = 10495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Compensation", description = "You've proven to be a very reliable individual, {name}.  As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance.\n\nFor now I will exchange your belt and gloves.  If we both see this through I shall make the rest of the pieces available to you.", sourceObjective = "Bring a Lightforge Belt and a set of Lightforge Gauntlets to Mokvar in Orgrimmar.", progress = "You're ready to perform the exchange?", completion = "Our agreement remains in place.  Just remember, this is but a taste of what awaits you.  Free me of this cursed fate and I will reward you with items of truly great power.", sourceObjectiveStatus = "unverified-source-field" }
quests[10496] = { id = 10496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", sourceObjective = "Return to Deliana in Ironforge with a set of Boots of Elements, a Kilt of Elements and Pauldrons of Elements.", progress = "You're back, {name}.  You must tell me all about what you've found out.  But first let us arrange for your reward.", completion = "I can't believe our lives are all but forfeit all because of a stupid medallion!  And you're sure Anthion mentioned Bodley?\n\nWell, you've done your job so let's get your reward out of the way.", sourceObjectiveStatus = "unverified-source-field" }
quests[10497] = { id = 10497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the amulet back together.  Return to Mokvar and tell him that Bodley is his only hope for finding the remaining pieces.  Speak to him about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", sourceObjective = "Return to Mokvar in Orgimmar with a set of Lightforge Boots, Lightforge Legplates and Lightforge Spaulders.", progress = "You've returned and I see in your eyes that you've much to tell me, {name}.  Let us take care of your reward first.", completion = "This curse was bestowed upon us but for a mere medallion.  Lord Valthalak certainly knows how to hold a grudge.\n\nWe'll endeavor to find the remaining pieces - hopefully before I meet an untimely demise.  But before that, let us see about your reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[10498] = { id = 10498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Best for Last", description = "That's an amazing story, {name}! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut.\n\nAs to your reward, I believe I have a few things that you'll really enjoy.", sourceObjective = "Give Deliana your Coif of Elements and Vest of Elements.", sourceObjectiveStatus = "unverified-source-field" }
quests[10499] = { id = 10499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Best for Last", description = "A truly amazing story, {name}! You have my thanks, and the heartfelt gratitude of all who were involved, I can assure you. Through your efforts we are delivered from the mistakes of our past.\n\nAs to your reward, I believe I have a few things that you have definitely earned and will truly enjoy.", sourceObjective = "Give Mokvar your Lightforge Helm and Lightforge Breastplate.", progress = "Are you ready to give me your Lightforge pieces in exchange for your new Soulforge Helm and Breastplate?", completion = "I will truly miss you, {name}. There is a debt that I owe you, which I may never be able to repay.\n\nEnjoy your new head and chest armor. May it protect you for a long time to come, and help you to achieve even greater honor!", sourceObjectiveStatus = "unverified-source-field" }
quests[10500] = { id = 10500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Your Help!", description = "Hello, I'm glad that you've decided to hear me out. The Horde needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, {name}!\n\nYou should go speak with the guy in charge, Warlord Gorchuk. What do you say, {class}? Will you help out with the vital preparations?", sourceObjective = "Speak with Warlord Gorchuk in Orgrimmar's Valley of Spirits.", sourceObjectiveStatus = "unverified-source-field" }
quests[10501] = { id = 10501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Your Help!", description = "Hello, I'm glad that you've decided to hear me out. The Alliance needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, {name}!\n\nYou should go speak with the guy in charge, Field Marshal Snowfall. What do you say, {class}? Will you help out with the vital preparations?", sourceObjective = "Speak with Field Marshal Snowfall in Ironforge's Military Ward.", sourceObjectiveStatus = "unverified-source-field" }
quests[10502] = { id = 10502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodmaul Ogres", description = "There is a threat to Sylvanaar far deadlier than the Horde at Thunderlord Stronghold.\n\nI'm speaking of the native ogres of these mountains.  Just to the south and east, down in the ravine, lives the Bloodmaul clan.  While they aren't the only group of ogres that threaten us here, they are the closest.\n\nI would have you head south through the Living Grove, and then go down the path to the east, which leads to their outpost.  Slay as many of the Bloodmaul ogres at Bloodmaul Outpost as you can.", sourceObjective = "Slay any 30 Bloodmaul Ogres at Bloodmaul Outpost.", progress = "Our scouts have reported that the Bloodmaul ogres have begun to creep up the switchback, which leads up to the Living Grove from their hold.\n\nIt is unfortunate that we cannot find a way to live together in peace with the ogres, but then, when have we ever been able to do so?", completion = "This is a good first step toward securing Sylvanaar and the grove.\n\nWith their ogres not so numerous, the Bloodmaul will think twice about attacking us here.\n\nNow, if only they were the only clan of ogres that we have to worry about.", sourceObjectiveStatus = "unverified-source-field" }
quests[10503] = { id = 10503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bladespire Threat", description = "There is a threat to Thunderlord Stronghold worse than the Alliance at Sylvanaar.\n\nI speak of the ogres of these mountains.  Just to the west, down in the ravine, lies the Bladespire clan.  While they aren't the only ogres, they are the closest and they're the ones that we defeated to take this place.\n\nHead north through the Jagged Ridge, and then down the path, which leads to their hold.  Slay as many of the Bladespire ogres and their raptors as you can at Bladespire Hold and the Bladespire Grounds.", sourceObjective = "Slay any 30 Bladespire Ogres and 10 Bladespire Raptors at Bladespire Hold and the Bladespire Grounds.", completion = "This is a good first step toward securing our position here against the ogres.\n\nWith their numbers decimated, the Bladespire will think twice about attempting to retake Thunderlord Stronghold.\n\nNow, if they were the only clan of ogres that we have to worry about.", sourceObjectiveStatus = "unverified-source-field" }
quests[10504] = { id = 10504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bladespire Ogres", description = "To the north of the Bloodmaul clan lies a threat more grave:  Bladespire Hold.\n\nThe Bladespire ogres are the strongest clan in the mountains, having the favor of the gronn known as Gruul the Dragonkiller, and his seven sons.\n\nNow that we've dealt with winnowing the Bloodmaul, it is time to turn our eye upon their rivals.\n\nFrom Bloodmaul Hold head north through the ravine until you come to Bladespire Hold and the Bladespire Grounds.  Slay as many of the Bladespire ogres therein as you can.", sourceObjective = "Slay any 30 Bladespire Ogres in Bladespire Hold and the Bladespire Grounds.", progress = "Bloodmaul or Bladespire, it doesn't matter.  All of the ogre clans fight against each other, vying for the dominance that comes with having the favor of Gruul the Dragonkiller.\n\nEach is still our enemy, regardless of who that favor has fallen to.", completion = "Your actions against both the Bloodmaul and the Bladespire ogre clans have gone a long way to securing Sylvanaar's future.  While we do not seek to expand past this patch of land, which we initially found empty, we will also not suffer those that would destroy us.\n\nAs you have done us good service, I would reward that service with the appreciation of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[10505] = { id = 10505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodmaul Ogres", description = "To the south of the Bladespire clan lies yet another threat:  Bloodmaul Outpost.\n\nWhile the Bloodmaul ogres are not the strongest clan in the mountains, not having the favor of the gronn known as Gruul the Dragonkiller, they run a close second.\n\nNow that we've dealt with winnowing the Bladespire, it is time to turn our eye upon their rivals.\n\nFrom Bladespire Hold head south through the ravine until you come to Bloodmaul Outpost.  Slay as many of the Bloodmaul ogres in the vicinity as you can.", sourceObjective = "Slay any 30 Bloodmaul Ogres at Bloodmaul Outpost.", completion = "Your actions against both the Bladespire and the Bloodmaul ogre clans have gone a long way to securing Thunderlord Stronghold's future.  We will not suffer those that would get in the way of our destiny here.\n\nAs you have done good work in destroying these ogres, I intend to reward you with the appreciation of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[10506] = { id = 10506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dire Situation", description = "With their wolf pack reduced, the Horde is looking for replacements.  Unfortunately there's another source nearby.\n\nThe Bloodmaul ogres in the ravine below to the east keep a strong pack as their own sentries.  I hated sending you to kill the Thunderlord wolves, so why don't we do something different this time?\n\nI've derived a magic powder from the dust that naturally falls off the wings of our fey drakes.  Sprinkle it on the Bloodmaul dire wolves to make them undesirable to the Horde.", sourceObjective = "Apply Rina's Diminution Powder to 5 of the Bloodmaul Dire Wolves at Bloodmaul Outpost and in Bloodmaul Ravine.", progress = "Any luck out there?  I know that it's dangerous work to be doing this amongst the Bloodmaul ogres, but if we can avoid the killing of any more animals, I'll be happy.", completion = "I'm glad to hear that it worked.  The fewer the number of Nature's creatures that have to die, the better.\n\nWith all that you've done for us already, I must say that I'm beginning to grow very fond of your company.\n\nTake care, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10507] = { id = 10507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning Point", description = "This is the chance we've been waiting for, {name}.  Not only have we uncovered the evidence we need to show our people who Kael'thas is really working for, but we can prove our strength by defeating his new masters.\n\nMy frail health prevents me from aiding you in person with this endeavor, but I will offer you an object that will allow me to project my powers across the continent.", sourceObjective = "Use Socrethar's Teleportation's Stone at Invasion Point: Overlord, north of Forge Base: Oblivion to transport your party to Socrethar's Landing. Once there, use Voren'thal's Presence to defeat Socrethar.\n\nPerforming quests for the Scryers will cause your Aldor reputation to decrease.", progress = "Is it done, {name}?", completion = "You are an individual of formidable power, {name}.  The Scryers are fortunate to count you as an ally.\n\nAs word of Kael's new allegiance spreads, more people will see things our way.  The fact that we can claim such a decisive victory against Kael'thas' new overlords puts us in a most favorable situation.\n\nI will not forget your deeds.", sourceObjectiveStatus = "unverified-source-field" }
quests[10508] = { id = 10508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for Voren'thal", description = "I don't want to send you to Voren'thal empty-handed.  It's not in my style to be underwhelming.\n\nTo gain access to Socrethar's Seat in the north, we'll need to use his own teleporters - locked by Socrethar's teleportation stone.  The first half of the stone is in the possession of Forgemaster Morug at Forge Base Oblivion.  The second half is held by the demon Silroth at Forge Base: Gehenna.\n\nObtain these and Voren'thal will be impressed beyond words.", sourceObjective = "Spymaster Thalodien at Area 52 wants you to obtain the First Half of Socrethar's Stone from Forgemaster Morug at Forge Base: Oblivion and the Second Half of Socrethar's Stone from Silroth at Forge Base: Gehenna.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", progress = "Have you obtained Socrethar's teleportation stone, {name}?", completion = "You do not cease to amaze me, {name}!  Good thing you're on our side.", sourceObjectiveStatus = "unverified-source-field" }
quests[10509] = { id = 10509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bound for Glory", description = "Now I can properly send you back to Shattrath City.  You've uncovered evidence of Kael'thas making pacts with the Burning Legion and you've got the key to the overlord's back door.\n\nMake sure Voren'thal doesn't topple over with excitement from the news - the old man's getting a bit fragile, if you know what I mean.  You'll find him inside the Seer's Library at the Scryer's Tier.", sourceObjective = "Bring Socrethar's Teleportation Stone to Voren'thal the Seer at the Scryer's Tier in Shattrath City.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", completion = "You have no idea what this will mean for the Scryers, {name}.  You will have to excuse me while I catch my breath and assess the situation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10510] = { id = 10510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Draenethyst Mine", description = "Well it's good to see someone who's willing to help out around here!\n\nBorgrim and I are part of the Explorers' League, and we're here to learn what we can of these mountains.  We've heard all sorts of tales, and I can't wait to get settled in and started.\n\nOne thing in particular has caught my attention.  The night elves speak of a place down in the ravine to the east known as the Draenethyst Mine.  It's at the south end of Bloodmaul Outpost.  I'd like some of the crystals that grow naturally therein.", sourceObjective = "Collect 5 Draenethyst Mine Crystals.", progress = "Isn't this exciting?  After all of the dirt and insects of Silithus, this place is like a paradise.", completion = "Ooh, by the looks of those, they're fine specimens.  I can't wait to get my examination tools unpacked and have a real look at them!\n\nThank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[10511] = { id = 10511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Brew", description = "If I'm going to start this vacation out right, then I'm going to need more brew.  Unfortunately, the elves know nothing of the fine art of fermentation.\n\nI overheard that the Bloodmaul ogres down in the ravine have plenty.  I'm willing to give it a try.\n\nDo me a favor?  Head south through the Living Grove and then down the ramp to the east into Bloodmaul Outpost and procure me some?  I hear they have big barrels of it laying around and that their brewmasters carry it around to all the other ogres.", sourceObjective = "Collect 11 Bloodmaul Brutebane Brew.", progress = "It's getting pretty dry around here.  How am I supposed to enjoy my vacation without something to drink?", completion = "What is that smell?  Oh no, don't tell me that's the ogre brew?!\n\nI'm almost afraid to try this stuff out.  Oh well, what the hell?  Bottoms up!", sourceObjectiveStatus = "unverified-source-field" }
quests[10512] = { id = 10512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting the Bladespire Tanked", description = "I'll not take another sip of that ill-smelling muck!  But it does give me an idea.\n\n<Borgrim gets a twinkle in his eye.>\n\nSo here's the plan.  We know that the Bloodmaul practically live off of this swill.  But I wonder what their enemies, the Bladespire ogres, think of it?\n\n{name}, I want you to take the rest of this rubbish and see if you can get the Bladespire ogres tanked.  You can find them by heading north from Bloodmaul Outpost through the ravine.", sourceObjective = "Use the Bloodmaul Brutebane Keg in an attempt to get 5 Bladespire Ogres drunk.", progress = "What's the word?  Are the Bladespire ogres as indiscriminate as the Bloodmaul, or did it nearly kill them like it did me?", completion = "Ah, hahaha!  That's what I thought.  I guess ogre's will drink anything.\n\nStupid, the lot of 'em!\n\nWell, I must say even though I didn't get my brew, you have given me a great start to my vacation.\n\nTell you what... we have all sorts of stuff here we don't really need.  Can I offer you something?", sourceObjectiveStatus = "unverified-source-field" }
quests[10513] = { id = 10513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oronok Torn-heart", description = "I do not know how we can acquire the spell that the spirits mentioned, {name}. Truth be told, I don't even know where we would start such a search.\n\n<Torlok stares off in the distance, lost in thought.>\n\nHrm... It is a long shot but it might be our only chance. There is an orc that I have seen visit this area before. I spoke to him briefly once. He is a hermit that claims to live above Coilskar Cistern to the northeast. Seek out this orc, Oronok Torn-heart.\n\nAs I said, it is a long shot.", sourceObjective = "Seek out Oronok Torn-heart on the Shattered Shelf - north of Coilskar Cistern.", completion = "Words of damnation? Never heard of 'em. Take my advice: Let the dead rest.\n\nBut since you've already come all this way, I could use some help with a few other matters. What do you say?", sourceObjectiveStatus = "unverified-source-field" }
quests[10514] = { id = 10514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Was A Lot Of Things...", description = "I've been a lot of things, stranger, but what I once was isn't what's important. What I am now is what matters and what I am now is a farmer.\n\nI use trained felboars to dig up tubers from the hardened earth of the Shattered Plains. Recently, though, flayers from a nest to the northeast have been attacking my animals, preventing me from gathering tubers.\n\nWould you go to the area north of here and gather tubers for me? Use this whistle while standing on a tuber mound and a boar will come dig one up!", sourceObjective = "Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley wants you to recover 10 Shadowmoon Tubers from the Shattered Plains.\n\nHe also wants Oronok's Boar Whistle back when you're done.", progress = "Get me those tubers!", completion = "You say there were a lot more of those flayers than you expected? Looks like it's time to take out the trash.", sourceObjectiveStatus = "unverified-source-field" }
quests[10515] = { id = 10515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson Learned", description = "We need to show those flayers what happens when you mess with Oronok's business!\n\nI want you to go back to the Shattered Plains and destroy every flayer egg that you see. They'll be deep in flayer territory so keep your guard up.", sourceObjective = "Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley wants you to destroy 10 Ravenous Flayer Eggs on the Shattered Plains.", progress = "No mercy!", completion = "That'll teach those damned, filthy animals not to kill my boars! Well done, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10516] = { id = 10516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trappings of a Vindicator", description = "I know it's strange, but I do want to stay in this cage.  It gives me the perfect opportunity to do what I came here for; to gather information on the Bladespire.\n\nI can leave at any time, but I would like to have my sword and shield back.\n\nTwo of their leaders have my trappings.  Droggam has my sword and Mugdorg has my shield.\n\nIf you have need, obtain and use the brew from Bloodmaul Outpost to the south to thin out their help and entice those two, but beware their sober guards who don't drink!", sourceObjective = "Collect Vindicator Vuuleen's Blade and Vindicator Vuuleen's Shield.", progress = "{class}, do you have my sword and shield?\n\nWhile I could leave at any time, it would be embarrassing for me to return to Sylvanaar without my trappings.", completion = "And now I owe you a great debt, for you have helped me to restore my honor.  But our work here is not yet over.", sourceObjectiveStatus = "unverified-source-field" }
quests[10517] = { id = 10517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorr'Dim, Your Time Has Come...", description = "The leader of Bladespire Hold is known as Gorr'Dim.  Trust me... the name is appropriate.\n\nStill, I wouldn't underestimate him.  He's crafty enough to have elevated his clan to be the favorite of Gruul the Dragonkiller and they now dominate these mountains.  And Gorr'Dim keeps an entourage about him at all times, including defenders who are sworn not to drink the Bloodmaul brew.\n\nFor the safety of Sylvanaar, I'm asking that you go back in there and deal with him.", sourceObjective = "Slay Gorr'Dim, leader of the Bladespire Hold ogres.", progress = "What was all of that noise?  Was that you dealing with Gorr'Dim?", completion = "Very well.  You're a very resourceful {class}, that's for certain.\n\nI wonder then if there's one more thing that you can do for myself and Sylvanaar?", sourceObjectiveStatus = "unverified-source-field" }
quests[10518] = { id = 10518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Planting the Banner", description = "I want you to steal the Bladespire banner from one of their champions and take it south to Bloodmaul Outpost.  Plant it atop their Northmaul Tower.\n\nThis will infuriate the Bloodmaul and they will attack you relentlessly.  But it will also keep their hatred focused on Bladespire Hold, and away from Sylvanaar.\n\nYou will know you have accomplished the deed when you have defeated Gurn Grubnosh and taken his helm.  Return it to Sylvanaar.\n\n{name}, this isn't going to be easy.  Take a  friend or two with you.", sourceObjective = "Use the Bladespire Banner atop the Northmaul Tower to lure Gurn Grubnosh. Collect the Bladespire Clan Banner and the Helm of Gurn Grubnosh.", progress = "What brings you to me?  Surely not more trouble with the Bloodmaul ogre clan?", completion = "Gurn Grubnosh's helm and a Bladespire banner?\n\nQuite clever of you and the vindicator to come up with that plan.\n\nBy keeping the attention of the Bloodmaul clan on Bladespire Hold, you've relieved the pressure that they were beginning to assert upon us here.\n\nPlease, {name}, accept a humble gift from Sylvanaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10519] = { id = 10519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cipher of Damnation - Truth and History", description = "<Oronok adjusts his posture and stands to his full height.>\n\nI had to be sure, {name}. And to be sure, I had to test you. Please excuse the little masquerade. I am as much a farmer as you are a felboar. Which is to say, not at all.\n\nIf you are to recover the Cipher of Damnation, you will need to listen to what I have to tell you. When you are ready, let me know and I will tell you the story.", sourceObjective = "Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley wants you to listen to his story. Speak to Oronok to begin hearing his story.", progress = "Be patient and listen, {name}.", completion = "Do you understand what must be done? Find the sons of Oronok. Find my boys...", sourceObjectiveStatus = "unverified-source-field" }
quests[10520] = { id = 10520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assisting Arch Druid Staghelm", description = "Excuse me {class}, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.\n\nPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.", sourceObjective = "Speak with Arch Druid Fandral Staghelm in Darnassus.", completion = "Well now, {class}... since you were informed that I was leading this research myself, you obviously came as quickly as you could.\n\nNow that you are here, be sure to pay attention the first time I tell you the details; I have no desire to repeat myself.", sourceObjectiveStatus = "unverified-source-field" }
quests[10521] = { id = 10521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grom'tor, Son of Oronok", description = "My first born, Grom'tor, left to search Coilskar Point - directly southwest of here.\n\nHe's the warrior in the family - ill-tempered and blood-thirsty... Traits he inherited from his mother. Search along the outskirts of Coilskar Point. If you see naga corpses, Grom'tor is sure to be close.\n\nWhen you find him, tell him this: \"We spill blood for just cause.\" It will let him know that you are a friend to Torn-heart and prevent your premature death.", sourceObjective = "Find Grom'tor, Son of Oronok at Coilskar Point in Shadowmoon Valley.", completion = "<Grom'tor grunts.>\n\nIt's good you came. This maggot just spilled its guts. We've got them now!", sourceObjectiveStatus = "unverified-source-field" }
quests[10522] = { id = 10522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cipher of Damnation - Grom'tor's Charge", description = "This naga filth is the sixth one I've interrogated today. He's got the fancy armor so I figured he knew something. Those other ones were useless.\n\n<Grom'tor points to the corpses of the naga around him.>\n\nI only had to beat him once and he told me everything.\n\nThe first part of the cipher is hidden in a naga chest at Coilskar Point or Coilskar Cistern, east of here. He says naga carry the keys. Kill 'em, take their keys and use them to open the Coilskar chests. Return to me when you find the cipher.", sourceObjective = "Grom'tor, Son of Oronok at Coilskar Point in Shadowmoon Valley wants you to recover the First Fragment of the Cipher of Damnation.", progress = "Any luck?", completion = "This must be taken back to father at once.", sourceObjectiveStatus = "unverified-source-field" }
quests[10523] = { id = 10523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cipher of Damnation - The First Fragment Recovered", description = "<Grom'tor wraps the documents up and places them in a lockbox.>\n\nTake this box to father. He awaits your return at the farm, northeast of here.\n\nTell him that I will be home soon. As soon as I am done having my fun...", sourceObjective = "Take Grom'tor's Lockbox to Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley.", progress = "You have succeeded?", completion = "When the Cipher of Damnation is reformed, we shall end this curse!", sourceObjectiveStatus = "unverified-source-field" }
quests[10524] = { id = 10524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderlord Clan Artifacts", description = "The artifact bears markings that indicate its origins as being created by the Thunderlord clan orcs.  These orcs used to live at Thunderlord Stronghold before they were changed into fel orcs.\n\nFor a time the Bladespire ogres inhabited the stronghold until recently when the Horde pushed them out.\n\nYou've heard of other artifacts that were lost.  A drum, an arrow and a tablet come to mind as objects that you know are being sought after.\n\nFind them in Bladespire Hold and return them to Rokgar Bloodgrip.", sourceObjective = "Collect the Thunderlord Clan Drum, Thunderlord Clan Arrow and the Thunderlord Clan Tablet.", progress = "Do I know you?", completion = "I do not believe my eyes!  If this is some sort of trick, I will flay the flesh from your bones, {class}!\n\nQuickly, let me examine these priceless artifacts before you break them with your clumsy hands.", sourceObjectiveStatus = "unverified-source-field" }
quests[10525] = { id = 10525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vision Guide", description = "{race} fool.  You almost destroyed the drum!\n\nI've worked too hard to get here, and my hands have been empty up until now.  At least you were able to succeed where the others only met with failure, or worse.\n\nIt is time to evoke a vision that will lead you to the last relic that I have been seeking.\n\nTake this fiery fragment of my soul.  Use it to transform your body into flame and denature your spirit into a vision guide that will shoot forth to reveal the location of the final Thunderlord relic.", sourceObjective = "Use the Fiery Soul Fragment to transform your spirit into a vision guide, which will reveal the location of the final Thunderlord artifact.", progress = "What did you see?  Tell me, I must know where it is!", completion = "The back of the Draenethyst Mine?  The Bloodmaul clan must have stolen it from the Bladespire ogres.\n\nBah!  That is too far away... too deep into Bloodmaul territory for me to travel.\n\nBut you.  You know the path.  You will go there in my stead!", sourceObjectiveStatus = "unverified-source-field" }
quests[10526] = { id = 10526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thunderspike", description = "If the vision that I granted you is true, then you must travel down into the ravine and to the south end of Bloodmaul Ravine.  There you will find the Draenethyst Mine.\n\nJourney to the back of the mine, and retrieve the Thunderspike.  Ignore everything else!  I have no interest in the crystals of the mine, nor the ogres therein.\n\nAs soon as you have the spear return it to me here!\n\nAnd, {name}, be very careful with it... I would hate to think what would happen to you should you break it.", sourceObjective = "Collect the Thunderspike.", progress = "The significance of these artifacts eludes you, I am sure.\n\nWhen we have all five, our right to the ownership of Thunderlord Stronghold will be secured through the appeasement of its dead spirits.\n\nDo you begin to grasp now why this is so important?  Do you understand why I have little patience for niceties?", completion = "Now I am impressed!  Do you have any idea how many others died attempting to retrieve all of these relics?\n\nWe are fortunate to have you working with us here, {name}.  Even if you are a bit slow.\n\nYou must allow me to reward your dedication to our cause.  Choose, but choose wisely.  When you are done, I will hand over the artifacts to appease the ghosts of Thunderlord Stronghold.", sourceObjectiveStatus = "unverified-source-field" }
quests[10527] = { id = 10527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ar'tor, Son of Oronok", description = "My youngest son, Ar'tor, left to search Illidari Point - far to the southwest, nestled between Legion Hold and Wildhammer Stronghold.\n\nWhile Ar'tor is a hunter of remarkable skill and an expert tracker, I fear that he may be in over his head this time. Illidari Point is the proving grounds for Illidan's demons. These are demons that left the Burning Legion to join the Betrayer!\n\nTravel to Illidari Point and find Ar'tor, {name}.", sourceObjective = "Find Ar'tor, Son of Oronok at Illidari Point in Shadowmoon Valley.", completion = "Ar'tor's body lies limp, suspended in mid-air. You have no idea how long he has been dead but your heart aches for Oronok.\n\nPerhaps you should try and get him down and take his corpse back to his father.", sourceObjectiveStatus = "unverified-source-field" }
quests[10528] = { id = 10528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonic Crystal Prisons", description = "From assessing the scene, you note that Ar'tor is being held in place by energy beams emanating from the crystals hovering around the rune. Try as you might, Ar'tor is unmovable.\n\nYou note that the crystals have an empty slot at their base - perhaps for a key. It also seems as if succubi periodically perform some sort of ritual at the site.\n\nSearch Illidari Point for their leader. Perhaps she holds the key to releasing Ar'tor.", sourceObjective = "Seek out and slay Painmistress Gabrissa at Illidari Point and return to the corpse of Ar'tor, Son of Oronok with the Crystalline Key.", progress = "Ar'tor hovers lifelessly before you.", completion = "You slide the crystalline key into the slots at the base of each of the demonic crystals.", sourceObjectiveStatus = "unverified-source-field" }
quests[10529] = { id = 10529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "Lieutenant Dawnrunner at Farstrider Retreat has requested an audience with all able hunters.  It would greatly benefit you to seek her out, {name}.  She is a beacon of wisdom for those of our calling.\n\nFarstrider Retreat lies south of Silvermoon City.", sourceObjective = "Speak with Lieutenant Dawnrunner at Farstrider Retreat in Eversong Woods.Lieutenant Dawnrunner at Farstrider Retreat has requested an audience with all able hunters. It would greatly benefit you to seek her out, {name}. She is a beacon of wisdom for those of our calling.\n\nFarstrider Retreat lies south of Silvermoon City.", sourceObjectiveStatus = "unverified-source-field" }
quests[10530] = { id = 10530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "Lieutenant Dawnrunner at Farstrider Retreat has requested an audience with all able hunters.  It would greatly benefit you to seek her out, {name}.  She is a beacon of wisdom for those of our calling.\n\nFarstrider Retreat lies south of Silvermoon City.", sourceObjective = "Speak with Lieutenant Dawnrunner at Farstrider Retreat in Eversong Woods.Lieutenant Dawnrunner at Farstrider Retreat has requested an audience with all able hunters. It would greatly benefit you to seek her out, {name}. She is a beacon of wisdom for those of our calling.\n\nFarstrider Retreat lies south of Silvermoon City.", sourceObjectiveStatus = "unverified-source-field" }
quests[10531] = { id = 10531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Arathi Basin!", description = "{name}, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.\n\nAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy's banner and rip it from its flag post!\n\nWhen you have done this to all four points, return to me.", sourceObjective = "Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10532] = { id = 10532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cut Arathor Supply Lines", description = "The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, {name}.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.", sourceObjective = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[10534] = { id = 10534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning Home", description = "A {race} {class}...\n\nYes, there was a priest of your order here recently, {name}.  He told me it was time you returned to the Exodar met with Caedmos.  There was a sense of urgency in his request, so I wouldn't take too long to see him.", sourceObjective = "Caedmos at the Exodar has requested you come see him.A {race} {class}...\n\nYes, there was a priest of your order here recently, {name}. He told me it was time you returned to the Exodar met with Caedmos. There was a sense of urgency in his request, so I wouldn't take too long to see him.", sourceObjectiveStatus = "unverified-source-field" }
quests[10535] = { id = 10535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Basin Resources!", description = "War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, {name}.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.", sourceObjective = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10537] = { id = 10537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lohn'goron, Bow of the Torn-heart", description = "It is a sign, {name}. Even in death, I cannot be stopped. Recovering a part of the Cipher of Damnation is my destiny. With your help, that destiny will be fulfilled.\n\nBefore we embark on that journey, I must have my longbow, Lohn'goron. It is a family heirloom that has been handed down from Torn-heart to Torn-heart for generations.\n\nMy instinct tells me that a demon stole it from my corpse. Kill the demons here until you find my bow.", sourceObjective = "The Spirit of Ar'tor at Illidari Point in Shadowmoon Valley wants you to recover Lohn'goron, Bow of the Torn-heart from the demons of the area.", progress = "Fear not, hero. When the time is right, I will assist you...", completion = "It means \"hero's sojourn\" in my native tongue. It rings true even now - in this era where our heroes have all died...\n\nIt seems as though one always rises.", sourceObjectiveStatus = "unverified-source-field" }
quests[10538] = { id = 10538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boiling Blood", description = "That last experiment was not a complete loss -- I did save a small bit of the blood you brought me.  Now boiled down, it should be free of whatever curses the Bleeding Hollow witches placed on their people's blood.\n\nI need more for study.  Go gather Bleeding Hollow blood from the orcs in Zeth'Gor.  When you've gathered the blood, bring it to their cursed cauldron and boil it.  Bring me the boiled blood.", sourceObjective = "Use Bleeding Hollow Blood at the Cursed Cauldron to make Boiled Blood. Bring 12 Boiled Blood to Apothecary Albreck at Spinebreaker Post.", progress = "Do you have the boiled blood, {name}?  I am eager to study it without an interruption this time...", completion = "Very good.  Now I can more easily perform my tests...\n\nThank you, {name}.  Your talents are considerable.", sourceObjectiveStatus = "unverified-source-field" }
quests[10539] = { id = 10539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning Home", description = "A {race} {class}...\n\nYes, there was a priest of your order here recently, {name}.  He told me it was time you returned to the Exodar met with Caedmos.  There was a sense of urgency in his request, so I wouldn't take too long to see him.", sourceObjective = "Caedmos at the Exodar has requested you come see him.A {race} {class}...\n\nYes, there was a priest of your order here recently, {name}. He told me it was time you returned to the Exodar met with Caedmos. There was a sense of urgency in his request, so I wouldn't take too long to see him.", sourceObjectiveStatus = "unverified-source-field" }
quests[10540] = { id = 10540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cipher of Damnation - Ar'tor's Charge", description = "At last, we are ready. I will bestow a piece of my spirit upon you, hero. It will guard you and help you in your battle against evil.\n\nYou must then travel south of here towards the back of Illidari Point. Hidden in the ether is a vile creature known as Veneratus the Many. My spirit hunter will call him out when he is near.\n\nDestroy Veneratus and take from his corpse the second part of the Cipher of Damnation.", sourceObjective = "The Spirit of Ar'tor at Illidari Point in Shadowmoon Valley wants you to recover the Second Fragment of the Cipher of Damnation from Veneratus the Many.\n\nCreatures attacked or damaged by the Spirit Hunter will not yield loot or experience.", progress = "The cipher must be recovered!", completion = "<Ar'tor fades in and out of existence.>\n\nIt would seem that my time is nearly at an end, hero.", sourceObjectiveStatus = "unverified-source-field" }
quests[10541] = { id = 10541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cipher of Damnation - The Second Fragment Recovered", description = "I thank you, hero. For without you, my spirit would forever remain in this cursed place.\n\n<Ar'tor hands you a spectral lockbox.>\n\nTake it and deliver it to my father at the farm, far to the northeast, above Coilskar Cistern... Inside are Lohn'goron and the second part of the cipher.\n\nHe will be sad to hear news of my death. Promise me that you will assure him that I died a free soul. Tell him that I see the hunting grounds and they are glorious. Tell him that I wait for him there...", sourceObjective = "Take Ar'tor's Lockbox to Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley.", progress = "<A single tear rolls down Oronok's cheek.>", completion = "<Oronok wipes the tear away and smiles at you.>\n\nThank you. I promise you, hero, a song of honor will be written in your name.", sourceObjectiveStatus = "unverified-source-field" }
quests[10542] = { id = 10542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Stole Me Hookah and Me Brews!", description = "T'chali used to be a pretty friendly troll.  Me come down here to teach the Bloodmaul how to brew their beer.  But once me do that, the Bloodmaul bury T'chali and leave him here to rot!\n\nThe worst part of it was that they stole me hookah!\n\nSo, you want to help T'chali?  You bring me hookah back.  T'chali think the ogres that stole it headed southwest over by the mine.\n\nAnd while you're in there, pick up some brews, too!", sourceObjective = "Collect T'chali's Hookah and 10 Bloodmaul Brutebane Brews.", progress = "Hey, you got me hookah and those brews yet?", completion = "Yes, that is what T'chali is talking about!  Though me not sure what those ogres put in there; that not T'chali's brand of tobacco that me smell in the hookah.\n\nNo matter, T'chali is happy.  Happy enough, in fact, to ask you to do something else.", sourceObjectiveStatus = "unverified-source-field" }
quests[10543] = { id = 10543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimnok and Korgaah, I Am For You!", description = "T'chali has been waiting for his revenge!\n\nThe day they bury T'chali and leave him to die, it was Grimnok Battleborn that led them.  And the next day it was Korgaah that come south to raid and kick T'chali in the head.\n\nI want them dead!\n\nYou will find Grimnok atop the Southmaul Tower in Bloodmaul Outpost.  You will find Korgaah in the top of a building at the north end of Bladespire Hold.  Korgaah has sober defenders, so use the brew to distract him away from them, because they won't drink.", sourceObjective = "Slay Grimnok Battleborn and Korgaah.", progress = "You think T'chali likes being this way?  No!\n\nSo, have you exacted me revenge yet?  Are Grimnok and Korgaah dead?", completion = "T'chali is pleased that Korgaah and Grimnok Battleborn are pushing up daisies just like him.\n\nBut T'chali's thirst for revenge is not quenched.  There's one more thing that you must do!", sourceObjectiveStatus = "unverified-source-field" }
quests[10544] = { id = 10544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Curse Upon Both of Your Clans!", description = "T'chali wants revenge on all of the ogres!\n\nT'chali was a powerful witch doctor in life.  If you reach into me grave you will find a wicked strong fetish.\n\nInvoke the fetish's magic at the entrances to the buildings and towers of both Bladespire Hold and Bloodmaul Outpost.  The voodoo you work will summon an evil spirit that you must defeat.  This in turn will curse that building.\n\nBeware, if you attempt to curse a building that is already cursed, you will call down another cursed spirit!", sourceObjective = "Use the Wicked Strong Fetish to curse 5 buildings or towers in Bladespire Hold and 2 in Bloodmaul Outpost.", progress = "T'chali does not want to speak again until {name} has used the fetish to curse the buildings and towers of both the Bladespire and Bloodmaul clans!", completion = "Hahaha, revenge is sweet!\n\nBut, T'chali can see you be interested in moving on now that you help him get his revenge.  I hear you, mon... life is for the living.\n\nTell you what, T'chali got lots of goodies still left here in his grave.  You pick the one you like best!", sourceObjectiveStatus = "unverified-source-field" }
quests[10545] = { id = 10545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bladespire Kegger", description = "As T'chali was saying, he helped out his Bloodmaul friends to make their brew.  But what T'chali did not say was why.\n\nThe Bloodmaul are in dire straits.  The Bladespire clan be crushing them, and they needed a new weapon to help out with their fight.\n\nThat's when T'chali came up with a great idea.  Why not make the perfect brew, one that strengthens you and weakens your enemy?  Only thing is, T'chali does not know if it works.\n\nSo, you gonna take this brew up to Bladespire Hold and see if it works!", sourceObjective = "Use the Bloodmaul Brutebane Keg to get 5 Bladespire Ogres drunk.", progress = "Tell T'chali... did the brew work?  Did the Bladespire ogres like it?", completion = "That's good news!  That brew is gonna come in handy with what T'chali is gonna ask you to do next.", sourceObjectiveStatus = "unverified-source-field" }
quests[10546] = { id = 10546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borak, Son of Oronok", description = "While Ar'tor was off hunting and Grom'tor was off fighting, Borak studied. Eventually he took up a vocation as a scholar and left for the wilds of Draenor. He returned home a few years ago a changed orc.\n\nHis heightened sense of awareness and mental acuity had forged a silent assassin.\n\nNow a confident and powerful orc, he has taken to recovering the most guarded piece of the cipher.\n\nFind Borak hiding near Eclipse Point, far to the south. He watches from the shadows of the bridge.", sourceObjective = "Find Borak, Son of Oronok near Eclipse Point in Shadowmoon Valley.", completion = "<Borak is silent for a moment.>\n\nI've been watching these blood elves for weeks now, trying to get a lock on where they've hidden the third part of the Cipher of Damnation.\n\nThus far, I've been unsuccessful in gathering any clues. The only thing I do know is that Illidan sends an envoy from the Black Temple here once a day.\n\nThis envoy is untouchable. I've shadowed him for a week, trying to figure out how to separate him from his bodyguard. Unfortunately, the bodyguard never leaves his side.", sourceObjectiveStatus = "unverified-source-field" }
quests[10547] = { id = 10547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Thistleheads and Eggs...", description = "I'd have given up had I not noticed... He's a Thistlehead. I couldn't place it at first but the signs are all there...\n\nNow if we could get our hands on some bloodthistle, we'd be in business.\n\nIn my travels, I met a shady Broken in Shattrath named Tobias.\n\nTobias made a business of trading bloodthistle to blood elves for rotten arakkoa eggs.\n\nDirectly west of here are arakkoa ruins. Search them for an egg and head to the lower city of Shattrath. That's where you'll find Tobias.", sourceObjective = "Borak, Son of Oronok at the bridge north of Eclipse Point wants you to find a Rotten Arakkoa Egg and deliver it to Tobias the Filth Gorger in Shattrath City, located in northwest Terokkar Forest.", progress = "<Tobias raises an eyebrow.>\n\nBloodthistle? Never heard of it... Are you a peacekeeper? You know you'd have to tell me if you were... I've got rights!", completion = "You've got a rotten arakkoa egg? Well why didn't you say so! I think we can do business.\n\n<Tobias smiles, exposing a mouthful of decay and filth.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10548] = { id = 10548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sad Truth", description = "Remember how I told you about the fat merchant who was looking for that ring?  As it turns out, he had his archeologist son looking for the thing and it didn't turn out so well.  By not so well I mean they killed him and shrunk his head.\n\nNow this might seem cold, calculating, and exceptionally callous, but he'd pay a lot to get his son's head back.  Sounds like the perfect job for you!\n\nGo east until you find the troll ruins of Zeb'Tela and Zeb'Nowa.  You're bound to find it one of the chests there.", sourceObjective = "Eralan in Tranquillien wants you to retrieve the Archeologist's Shrunken Head from one of the chests in Zeb'Tela or Zeb'Nowa.", progress = "How's the head hunting?", completion = "Oh, wow.  That is not pretty.  I'm sure the merchant will appreciate it more than me.\n\nAs payment, the merchant offered to buy one of my special stock items for you, so take your pick handsome!", sourceObjectiveStatus = "unverified-source-field" }
quests[10550] = { id = 10550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bundle of Bloodthistle", description = "I wasn't lying. That egg was incredible. Where did you get it from?\n\nWell, if you ever need more bloodthistle, you know where I am and what I need.\n\nHere's a bundle of the stuff. Take it back to your benefactor.", sourceObjective = "Take the Bundle of Bloodthistle back to Borak, Son of Oronok at the bridge near Eclipse Point in Shadowmoon Valley.", progress = "Do you have the bloodthistle?", completion = "Now to set the trap!", sourceObjectiveStatus = "unverified-source-field" }
quests[10551] = { id = 10551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allegiance to the Aldor", sourceObjective = "Are you certain of your choice, {name}?  The Aldor will welcome you as an ally, but the Scryers will not easily forgive your decision.", sourceObjectiveStatus = "unverified-source-field" }
quests[10552] = { id = 10552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allegiance to the Scryers", sourceObjective = "Are you certain of your choice, {name}?  The Scryers will welcome you as an ally, but the Aldor will not easily forgive your decision.", sourceObjectiveStatus = "unverified-source-field" }
quests[10553] = { id = 10553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voren'thal the Seer", description = "Now that you've chosen a side, {name}, you should meet the Scryers' leader.\n\nYou will find Voren'thal the Seer inside the Seer's Library at the Scryer's Tier.\n\nSee if you can be of assistance to him.  He will be glad to hear you've decided to lend them a hand.", sourceObjective = "Speak to Voren'thal the Seer inside the Seer's Library at the Scryer's Tier in Shattrath City.\n\nPerforming quests for the Scryers will cause your Aldor reputation level to decrease.", completion = "Khadgar sends a new recruit?  Let us put you to work, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10554] = { id = 10554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ishanah", description = "Now that you've decided to side with the Aldor, you'd do well to introduce yourself to their leader.  You will find High Priestess Ishanah inside the Shrine of Unending Light.", sourceObjective = "Speak to Ishanah inside the Shrine of Unending Light at the Aldor Rise in Shattrath City.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", completion = "Welcome, {name}.  I'm glad to hear you've decided to join us in our mission.  May the Light always protect you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10555] = { id = 10555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malaise", description = "The magic practiced by the Lashh'an arakkoa is unnatural. They rip out handfuls-clawfuls?-of their own feathers as reagents!\n\nThat doesn't sound like good magic to me. I've come here to learn more about their spells. Unfortunately getting close is too much for me.\n\nYou could succeed: cast one of their spells on yourself, then return to me. You'll have to find one of their spellbooks, high up in the trees of Veil Lashh.\n\nAnd unless you've grown feathers I can't see, you'll need to get some of those.", sourceObjective = "Collect 18 Plucked Lashh'an Feathers.", progress = "From the crude pictographs on the pages of the aged tome, you discern that a large number of Lashh'an feathers will be needed when casting the spells contained within.", completion = "Flipping through the pages of the scratched notes and spindly script of the Lashh'an arakkoa, you find a page with a pictogram of the circles of power you have seen in Veil Lashh.", sourceObjectiveStatus = "unverified-source-field" }
quests[10556] = { id = 10556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scratches", description = "The pictograms indicate using feathers to cast the spell at one of the circles of power in Veil Lashh.\n\nConfusing iconography seems to show an arakkoa being suffused with the spirit of a kaliri.", sourceObjective = "Use the Fistful of Feathers on the Lashh'an Spell Circle.", progress = "This is exciting! I can't wait to examine the workings of the spell.", completion = "I don't know what to say. This spell is very strange. It is not a simple conjuration or enchantment, but some sort of communion or communication spell.\n\nI'm not sure what to make of it, {name}. I'll have to think about it some more.\n\nBut thanks for your help, anyways! I'm sure I'll think through this sooner or later.", sourceObjectiveStatus = "unverified-source-field" }
quests[10557] = { id = 10557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test Flight: The Zephyrium Capacitorium", description = "I built an amazing device, the Zephyrium Capacitorium, and I'm sure it'll work perfectly, but... do you want to help me test it?\n\nThere's plenty of hazard pay!\n\nSpeak with my twin over there, Rally. Good luck, {name}. Come back after your experiment.  Or... if that's not possible due to sustained injuries, your next of kin can report to collect your pay.", sourceObjective = "Speak with Rally Zapnabber and use the Zephyrium Capacitorium.", progress = "Don't be afraid!  This is for science, and science is painful!", completion = "Wow, you made it!  And not a single bruise or compound fracture!  See, I told you everything would work out!\n\nHere's your pay, {name}, though I factored in medical expenses and you don't need those... so that's a bonus for you!", sourceObjectiveStatus = "unverified-source-field" }
quests[10558] = { id = 10558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revered Among Honor Hold", description = "You've proven your worth to our cause, {name}.  One such as yourself could one day become a great leader.\n\nContinue to fight our enemies in the Shattered Halls and gain renown among my men.  If you live up to my expectations I will have greater tasks to ask of you.", sourceObjective = "Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula wants you to become revered with Honor Hold by fighting Fel Orcs inside the Shattered Halls of Hellfire Citadel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10559] = { id = 10559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revered Among Thrallmar", description = "You've proven yourself time and again, {class}.  Yet more trials await you.\n\nContinue to fight the Fel Horde inside the Shattered Halls of Hellfire Citadel and your name will be known to all of Thrall's followers in this land.", sourceObjective = "Nazgrel at Thrallmar in Hellfire Peninsula wants you to become revered with Thrallmar by fighting the Fel Orcs inside the Shattered Halls of Hellfire Citadel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10560] = { id = 10560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revered Among the Sha'tar", description = "<The calming melodic tones projected by A'dal become more hushed and somber.>\n\n<You are shown the large naaru structure known as Tempest Keep.  It is now inhabited by the forces of Kael'thas and its power used for nefarious ends.  A'dal promises you greater tasks once you've done your part to take back Tempest Keep.>", sourceObjective = "A'dal in Shattrath City wants you to become revered with the Sha'tar by defeating the forces of Kael'thas inside Tempest Keep.", sourceObjectiveStatus = "unverified-source-field" }
quests[10561] = { id = 10561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revered Among the Keepers of Time", description = "You've proven yourself to us, {race}.  The timeline is not yet safe, however.\n\nWe're in need of true champions and you may prove to be one.\n\nContinue to defend the events of the past from intruders and you'll get the renown you deserve.", sourceObjective = "Andormu inside the Caverns of Time in Tanaris wants you to become revered with the Keepers of Time by continuing to defend the events of Old Hillsbrad and the Black Morass inside the Caverns of Time.", sourceObjectiveStatus = "unverified-source-field" }
quests[10562] = { id = 10562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besieged!", description = "Don't let your guard down, {race}. We're under constant assault from the Burning Legion.\n\nFrom their base of Legion Hold to the northwest, the demons rain down a ceaseless stream of infernals. As quickly as we can kill them, the new meteors impact and begin a new wave of attacks.\n\nMy men are ragged and exhausted. I don't know how much longer they'll hold out. Please, {name}, lend your help to our defenses. Take your place on the line and halt the advance of the infernals!", sourceObjective = "Wing Commander Nuainn, outside of Wildhammer Stronghold, wants you to kill 10 Infernal Attackers.", progress = "Have you tired already, {class}?", completion = "Thank you for relieving my men, {name}. With your help, and that of others, we may yet hold out. Unfortunately, merely holding out is not enough. We must go on the offensive.", sourceObjectiveStatus = "unverified-source-field" }
quests[10563] = { id = 10563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Legion Hold", description = "The fortress of Legion Hold is nigh impregnable, and to be completely honest, I can't spare the forces for an assault. Our hopes are riding on you, {name}.\n\nWhat little information we've been able to gather indicates that the Legion stocks and prepares its infernals at the hold. With the help of a disguise I'll give you, you must sneak into Legion Hold and learn about their plans. Your best hope is to intercept or overhear communication between their commanders. Good luck, {name}.", sourceObjective = "Make your way to Legion Hold and locate the Legion Communication Device. While standing near the communication device, use your disguise and learn about the Legion's plans. Return to Wing Commander Nuainn at Wildhammer Stronghold when you've completed your mission.", progress = "What did you discover?", completion = "<Wing Commander Nuainn listens to your report, growing more alarmed with each sentence.>\n\nSo you're saying they have more than enough infernals to intensify the bombardment? If we don't stop them before they can put the next phase of their plan into motion, Wildhammer Stronghold is finished.", sourceObjectiveStatus = "unverified-source-field" }
quests[10564] = { id = 10564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blast the Infernals!", description = "The device we've assembled won't win any beauty contests, but it should be capable of destroying the infernals amassed at Legion Hold. Judging from what the fel reaver power core's energy did to the Fetid Pool, it holds a respectable amount of explosive power.\n\nIf you set the device off in the middle of the green glyph at the hold, it should be in range to hit all of the infernals.", sourceObjective = "Use the Fel Bomb while standing on the green glyph in Legion Hold, then report to Wing Commander Nuainn at Wildhammer Stronghold.", progress = "Have you found a way to destroy the Legion's infernal stockpile?", completion = "Well done, {name}! I wish I could say that the Legion would give up after a setback like this, but you and I know better than that. The Deathforge that you learned about during your reconnaissance mission will be our next target.", sourceObjectiveStatus = "unverified-source-field" }
quests[10565] = { id = 10565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stones of Vekh'nir", description = "The arakkoa of Vekh'nir have been a thorn in our sides for many years. Some strange religion guides them, a religion which has the arakkoa in a frenzy of activity. They carry these crystals with them now, which they have turned to some dark purpose.\n\nI know something of their rituals. They take the crystals to their spell circles to infuse them. We at the village would like to know more. Waylay a few of the arakkoa until you find a crystal, charge it, then return it to me.", sourceObjective = "Collect and use a Vekh'nir Crystal at the Vekh'nir Spell Circle to create a Charged Vekh'nir Crystal.", progress = "The Vekh'nir arakkoa have been benign for many years, but now something has stirred them.", completion = "Ah, look how it glows! I must try this at once.", sourceObjectiveStatus = "unverified-source-field" }
quests[10566] = { id = 10566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial and Error", description = "I've fashioned four wands that I believe will enhance the power of the arakkoa's crystals. Take these wands to Trogma's Claim, and try them on the ogre slaves.\n\nYou'll need to find an infused crystal off of the arakkoa in the area.\n\nWhen you figure out which is best, come back to me.", sourceObjective = "Try out each of Dertrok's wands on an Arakkoa Ogre Slave. Each wand will require an Infused Vekh'nir Crystal to use.", progress = "I eagerly await your results, {name}.", completion = "This information will be very helpful, {name}. I will further refine that design and see if we can't expand its utility.", sourceObjectiveStatus = "unverified-source-field" }
quests[10567] = { id = 10567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creating the Pendant", description = "The arakkoa of Ruaan Weald elevate from their flock the Harbingers of the Raven, the heralds of their god.\n\nThey believe that the Harbingers watch over them from the sky, where they receive the teachings of the Raven, and descend to pass this message along.\n\nThe Harbingers hold a powerful sway over the souls of the arakkoa. They use magical pendants, which we need.\n\nAttract one of the Harbingers by slaying its flock and taking their claws. Place the claws upon the altar to get his attention.", sourceObjective = "Collect 6 Ruuan'ok Claws and use them at the Ruaan'ok Oracle Circle to summon a Harbinger of the Raven. Kill it to collect its Harbinger's Pendant.", progress = "Once the Harbinger is aware of your attack upon his flock, he will be quick to respond.", completion = "You have it!\n\nWith this pendant, I will be able to attune you to the arakkoa of Grishnath in such a way that will enable you to comprehend their speech.\n\nWith this, we may gain further understanding of the arakkoa, and the nature of the Raven. I will need your help to do this.", sourceObjectiveStatus = "unverified-source-field" }
quests[10568] = { id = 10568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tablets of Baa'ri", description = "Years ago, the dreaded warlock known as Gul'dan raised the volcano in the middle of Shadowmoon.  The draenei village of Baa'ri, to the southwest, was buried under the lava along with its inhabitants and artifacts of religious importance.\n\nThe treacherous tribe of Broken known as the Ashtongue has been ordered by Illidan to excavate the area.  We must use this opportunity to recover the Tablets of Baa'ri, an ancient text rumored to hold the secrets of the Temple of Karabor, now known as the Black Temple.", sourceObjective = "Anchorite Ceyla at the Altar of Sha'tar wants you to collect 12 Baa'ri Tablets from the ground and from Ashtongue Workers at the Ruins of Baa'ri.\n\nCompleting quests with the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you found the tablets yet, {name}?", completion = "The Baa'ri tablets!  Yes, this might provide us with very useful information.", sourceObjectiveStatus = "unverified-source-field" }
quests[10569] = { id = 10569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sketh'lon Wreckage", description = "Our scouts have brought back disturbing reports from the ruined arakkoa encampments in the area.\n\nThe ghosts of powerful arakkoa magicians wield powers we never thought they possessed. They seem to be organizing, as though preparing for something, but our knowledge is limited. We cannot afford to remain ignorant!\n\nTravel north to the Sketh'lon Wreckage, to the northwest of the Deathforge and search for signs of their motives.", sourceObjective = "Recover the Skethlon Commander's Journal Page 1, Skethlon Commander's Journal Page 2, and Skethlon Commander's Journal Page 3 from the Dark Conclave arakkoa at the Sketh'lon Wreckage to Gryphonrider Kieran.", progress = "What have you discovered?", completion = "<Kieran leafs through the journal pages.>\n\nMuch of this is unintelligible, but I can make out bits here and there about preparations for a spell gone awry, casualties, and a deteriorating situation. There's also a curious note here about a 'deserter.'", sourceObjectiveStatus = "unverified-source-field" }
quests[10570] = { id = 10570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Catch A Thistlehead", description = "<Borak takes the bundle of bloodthistle from you and places it to his nose.>\n\nPungent...\n\nNow, take this bundle and place it at the other end of this bridge. When the envoy makes his daily rounds, he will be compelled to pick it up - without his bodyguard. You see, blood elves look down upon bloodthistle addicts. If any of his compatriots ever found out...\n\nAll you need to do is lie in wait for him to dismiss his bodyguard. When he is alone, make your strike! Kill him and take the missive.", sourceObjective = "Borak, Son of Oronok at the bridge near Eclipse Point in Shadowmoon Valley wants you to recover the Stormrage Missive.", progress = "Be quick about it, boy.", completion = "<Borak takes the missive from you and begins to read.>\n\nClever bastards! This is a directive from Illidan that dictates where the cipher is to be hidden next. Apparently, they keep it moving. It does not tell us where it currently rests... If only we could deliver the missive now that we know the next location.\n\nToo bad the seal on the missive is broken, rendering it unusable.\n\nHrm... Yet...", sourceObjectiveStatus = "unverified-source-field" }
quests[10571] = { id = 10571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oronu the Elder", description = "According to the tablets, an artifact known as a Medallion of Karabor was kept at Baa'ri.  Only the highest-ranking draenei priests were granted these, as they allowed unfettered access into the Temple of Karabor.\n\nWe must find out whether the Ashtongue have recovered the medallion that was kept at Baa'ri yet.  Its power would provide great aid in our fight against Illidan.\n\nAkama's lieutenant at Baa'ri, Oronu the Elder, receives written orders from him daily.  Obtain them and bring them to me.", sourceObjective = "Anchorite Ceyla at the Altar of Sha'tar wants you to obtain the Orders from Akama from Oronu the Elder at the Ruins of Baa'ri.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Any news yet, {name}?  Time is not on our side.", completion = "Akama's very own handwriting.  It is truly sad to think of what became of one as wise and beloved as he.", sourceObjectiveStatus = "unverified-source-field" }
quests[10572] = { id = 10572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting Up the Bomb", description = "We cannot permit the Legion to carry out its plan to destroy Wildhammer Stronghold on their march to the Black Temple.\n\nThere's only one way to stop them, {name}. You must create an explosive large enough to destroy the Legion's entire stockpile of infernals at the hold.\n\nThe Fetid Pool near Legion Hold holds an old fel reaver power core you could use as the base of your device. Search the other wreckage near the fel reaver for armor plating we might be able to make a casing from.", sourceObjective = "Obtain a Fel Reaver Power Core and a Fel Reaver Armor Plate and bring them to Wing Commander Nuainn at Wildhammer Stronghold.", progress = "<You hand the materials to the wing commander.>", completion = "<The wing commander inserts the power core into the armor plates and seals the device shut, nodding.>\n\nThis should do the trick. Should make quite an explosion too, if I do say so m'self.", sourceObjectiveStatus = "unverified-source-field" }
quests[10573] = { id = 10573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deathforge", description = "From your findings at Legion Hold, we know that the Legion's Shadow Council allies are producing infernals in the Deathforge. I've dispatched a small scouting party to keep watch over the area, but they're not able to accomplish everything we need.\n\nIf the Deathforge is left alone to operate, they'll rebuild the infernal stockpile that you destroyed at Legion Hold.\n\nI want you to meet up with Stormer Ewan Wildwing, at the Deathforge Tower, to the northwest, overlooking the Deathforge itself.", sourceObjective = "Report to Stormer Ewan Wildwing at the Deathforge Tower.", completion = "<The dwarf nods.>\n\nIt'll be good to have the backup. We've gathered some preliminary information on what the Shadow Council is up to in there, but I'll feel better once we're able to start taking action against them.", sourceObjectiveStatus = "unverified-source-field" }
quests[10574] = { id = 10574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ashtongue Corruptors", description = "According to Akama's letter, four fragments of the medallion were unearthed and given to the Ashtongue Corruptors.  These dreaded Broken were once powerful shaman who now defile the very elements they revered.\n\nHaalum, Corruptor of Air, can be found at Netherwing Pass.  Eykenen and Uylaru, Corruptors of Earth and Fire, were last seen at the Fel Pits near the Hand of Gul'dan.  Lakaan, Corruptor of Water, is rumored to be near Coilskar Point.\n\nFind them and obtain the medallion fragments.", sourceObjective = "Obtain the four medallion fragments from Haalum, Eykenen, Lakaan and Uylaru and return to Anchorite Ceyla at the Altar of Sha'tar in Shadowmoon Valley.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you obtained the four medallion fragments, {name}?", completion = "Yes!  The four fragments of the medallion.  Now to put them together...", sourceObjectiveStatus = "unverified-source-field" }
quests[10575] = { id = 10575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Cage", description = "The fragments you obtained are only half of the medallion.  The Ashtongue leader, Akama, must have kept the other half.\n\nI dread to ask this of you, as Akama is both evil and cunning.\n\nHe and the Ashtongue Deathsworn - the vilest and most brutal of the tribe - are rumored to run a torture chamber inside the Warden's Cage.\n\nI want you to find that dreaded prison,  and find the whereabouts of Akama.  His second in command at the location is a Broken known as Sanoru - interrogate him if you have to.", sourceObjective = "Anchorite Ceyla wants you to enter the Warden's Cage, south of the Ruins of Baa'ri and interrogate Sanoru on Akama's whereabouts.\n\nCompleting quests for the Aldor will cause your Scryers reputation to decrease.", completion = "We've been expecting you, {name}.  Akama said you would arrive sooner or later.", sourceObjectiveStatus = "unverified-source-field" }
quests[10576] = { id = 10576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadowmoon Shuffle", description = "<Borak looks you up and down.>\n\nThis is going to be tricky, but I think I can make it work.\n\nI can disguise you as one of these Illidari blood elves, {name}. What I need first, though, are several pieces of their armor. It is imperative that the armor be clean. No blood stains! We want to avoid suspicion.\n\nBring me the gear and I'll take care of the rest of the disguise.\n\nOnce the disguise is assembled, you're going to deliver the message to the Grand Commander - in person.", sourceObjective = "Borak, Son of Oronok at the bridge near Eclipse Point in Shadowmoon Valley wants you to recover 6 pieces of Eclipsion Armor.", progress = "It's far too complicated, {race}. You wouldn't understand.", completion = "Well done, {name}. I hope you are a good actor. The next step in my grand plan is going to require some theatrics!", sourceObjectiveStatus = "unverified-source-field" }
quests[10577] = { id = 10577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Illidan Wants, Illidan Gets...", description = "Take this disguise and enter Eclipse Point. Once inside, use the disguise to cloak yourself. The Eclipsion blood elves will be unable to see through the disguise, thereby granting you safe passage to Grand Commander Ruusk.\n\nOnce you find Ruusk, tell him where next to move the cipher. You're going to have to act your heart out, {name}. Play it off as if you are his superior, delivering a message from his lord. That should do it!\n\nOh - watch out for the dragonhawks as they see through the disguise.", sourceObjective = "Borak, Son of Oronok at the bridge near Eclipse Point in Shadowmoon Valley wants you to Deliver Illidan's Message to Grand Commander Ruusk at Eclipse Point.", progress = "The disguise is delicate. Almost any action, aside from walking, will disrupt the magic holding it together.", completion = "Now all you need to do is go get the cipher. Easy, right?", sourceObjectiveStatus = "unverified-source-field" }
quests[10578] = { id = 10578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cipher of Damnation - Borak's Charge", description = "That Cipher fragment will never reach Zuluhed. You're going to ambush Ruul the Darkener and his transport before it has a chance to make the delivery.\n\nThe Dragonmaw Fortress is directly east of here, across the Netherwing Fields. Somewhere between Dragonmaw Fortress and the Sanctum of the Stars is where you'll find Ruul. Strike hard and strike fast! And {name}, from the sound of it, this Ruul is going to be tough. Keep your guard up.\n\nReturn the Cipher to me should you succeed.", sourceObjective = "Borak, Son of Oronok at the bridge near Eclipse Point in Shadowmoon Valley wants you to recover the Third Part of the Cipher of Damnation from Ruul the Darkener.\n\nThis mission will require a group.", progress = "You must act quickly!", completion = "Finally! The cipher fragment is ours!\n\n<Borak places the fragment into a box.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10579] = { id = 10579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cipher of Damnation - The Third Fragment Recovered", description = "Take this box to my father. He still resides at Oronok's Farm, far to the north, above Coilskar Cistern. When all three fragments are pieced together, the ancient words will be known once more.\n\nGood luck, {name}. Tell my father that I will be home soon.", sourceObjective = "Take Borak's Lockbox to Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley.", progress = "{name}!", completion = "As soon as all three of the fragments of the cipher are together, the ancient words will be known.\n\nRecovery of this fragment was no doubt challenging. You must be rewarded for such heroism.", sourceObjectiveStatus = "unverified-source-field" }
quests[10580] = { id = 10580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Did Those Darn Gnomes Go?", description = "Despite the good that we've done here, I feel bad about one thing: driving Toshley and his gnome friends away.\n\nWe had no choice; they were making a mess of our efforts in the grove with all of their technology and experimentation.\n\nI would appreciate it if you would find out what became of them.  Last we heard, they headed east across the bridge.  I'm certain that they must have turned south, away from Thunderlord Stronghold.\n\nLook for a clue as to their whereabouts in the southern Jagged Ridge.", sourceObjective = "Search the southern area of the Jagged Ridge of the Blade's Edge Mountains for a clue as to the whereabouts of Toshley and the other gnomes.", completion = "SYLVANAAR?  COMMANDER SKYSHADOW?\n\nTHIS DOES NOT COMPUTE!\n\nBACK AWAY BEFORE I AM FORCED TO PLAY LOUD SOUNDS AT YOU!", sourceObjectiveStatus = "unverified-source-field" }
quests[10581] = { id = 10581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Follow the Breadcrumbs", description = "VERY WELL, I AM HEREBY WARNING YOU THAT YOU WILL FIND NOTHING UP ON THE RIDGE.\n\nDO NOT FOLLOW THE TRAIL OF SPARE PARTS THAT LEAD TO TOSHLEY'S STATION!  YOU WILL NOT FIND TOSHLEY, NOR ANY OTHER GNOME THERE.", sourceObjective = "Follow the trail of spare parts up the ramp to the Razor Ridge. Speak with Toshley at Toshley's Station in the Blade's Edge Mountains.", completion = "Alright, you want to make yourself useful?  Good, I have just the thing that you can prove yourself with.\n\nI think you'll like it.", sourceObjectiveStatus = "unverified-source-field" }
